const FP_CONFIG_SELECT_COLS='client_id, enabled, reminders_enabled, razorpay_key_id, razorpay_webhook_secret, admin_phone_numbers, tax_reserve_pct, default_currency, reminder_template_name, reminder_template_category, reminder_template_language';
// Shared by GET and PATCH (the latter now returns the fresh row instead of a bare {ok:true} — the
// Settings tab's saveFpConfig assigns the response straight into fpConfig, so an {ok:true}-only
// reply was quietly wiping every other field client-side until the next full page load).
function fpConfigResponseShape(row, cid){
  if(!row) return {client_id:Number(cid), enabled:1, reminders_enabled:1, razorpay_connected:false, admin_phone_numbers:[], tax_reserve_pct:null, default_currency:null, reminder_template_name:null, reminder_template_category:null, reminder_template_language:null};
  return {...row, razorpay_connected:!!(row.razorpay_key_id&&row.razorpay_webhook_secret), admin_phone_numbers:engineParseJsonField(row.admin_phone_numbers, [])};
}
async function handleFpConfigGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const row=await env.DB.prepare(`SELECT ${FP_CONFIG_SELECT_COLS} FROM fp_config WHERE client_id=?`).bind(Number(payload.cid)).first();
  return json(fpConfigResponseShape(row, payload.cid));
}
async function handleFpConfigUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const now=new Date().toISOString();
  // Ensure a row exists first (defaults, no-op if already present), then apply only the fields
  // actually provided in a plain UPDATE — keeps the insert branch's placeholders and the dynamic
  // update branch's placeholders from ever needing to line up positionally in one statement.
  await env.DB.prepare(`INSERT INTO fp_config (client_id, enabled, reminders_enabled, updated_at) VALUES (?,1,1,?)
    ON CONFLICT(client_id) DO NOTHING`).bind(Number(payload.cid), now).run();
  const sets=['updated_at=?'], vals=[now];
  if(body.enabled!==undefined){ sets.push('enabled=?'); vals.push(body.enabled?1:0); }
  if(body.reminders_enabled!==undefined){ sets.push('reminders_enabled=?'); vals.push(body.reminders_enabled?1:0); }
  if(body.razorpay_key_id!==undefined){ sets.push('razorpay_key_id=?'); vals.push(String(body.razorpay_key_id||'').trim()); }
  if(body.razorpay_key_secret!==undefined){ sets.push('razorpay_key_secret=?'); vals.push(String(body.razorpay_key_secret||'').trim()); }
  if(body.razorpay_webhook_secret!==undefined){ sets.push('razorpay_webhook_secret=?'); vals.push(String(body.razorpay_webhook_secret||'').trim()); }
  // Admin bookkeeping numbers — see fpIsAdminPhone's own comment. Accepts either a real array or a
  // comma-separated string (the Settings tab's own textarea/input sends the latter), capped at 10
  // so this can never grow into an unbounded list by accident.
  if(body.admin_phone_numbers!==undefined){
    const nums=(Array.isArray(body.admin_phone_numbers)?body.admin_phone_numbers:String(body.admin_phone_numbers||'').split(','))
      .map(n=>String(n||'').trim()).filter(Boolean).slice(0,10);
    sets.push('admin_phone_numbers=?'); vals.push(JSON.stringify(nums));
  }
  if(body.tax_reserve_pct!==undefined){
    sets.push('tax_reserve_pct=?');
    vals.push(body.tax_reserve_pct===null||body.tax_reserve_pct===''?null:Math.max(0,Math.min(100,Number(body.tax_reserve_pct)||0)));
  }
  // Single account-wide default currency (migration 0036) — read by the frontend as the shared
  // default for every currency field across Documents/Expense Entry/Vendor Bills/Financial
  // Planning, instead of each modal hardcoding its own fallback.
  if(body.default_currency!==undefined){ sets.push('default_currency=?'); vals.push(String(body.default_currency||'').trim().slice(0,10).toUpperCase()||null); }
  // WhatsApp template used by the overdue-payment reminder sweep (fpSendRemindersForClient) —
  // required because that sweep runs off a daily cron, never inside a customer-initiated 24h
  // session window, so only an approved template can reliably reach the customer.
  if(body.reminder_template_name!==undefined){ sets.push('reminder_template_name=?'); vals.push(String(body.reminder_template_name||'').trim()||null); }
  if(body.reminder_template_category!==undefined){ sets.push('reminder_template_category=?'); vals.push(String(body.reminder_template_category||'').trim()||null); }
  if(body.reminder_template_language!==undefined){ sets.push('reminder_template_language=?'); vals.push(String(body.reminder_template_language||'').trim()||null); }
  vals.push(Number(payload.cid));
  await env.DB.prepare(`UPDATE fp_config SET ${sets.join(', ')} WHERE client_id=?`).bind(...vals).run();
  const row=await env.DB.prepare(`SELECT ${FP_CONFIG_SELECT_COLS} FROM fp_config WHERE client_id=?`).bind(Number(payload.cid)).first();
  return json(fpConfigResponseShape(row, payload.cid));
}

// Audit trail for the overdue-reminder sweep (fpSendRemindersForClient/fpLogReminderAttempt) —
// lets the Settings tab show exactly what was sent, skipped, or failed, and why, instead of the
// old silent catch(e){} that left no record at all.
async function handleFpReminderLog(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {results}=await env.DB.prepare(
    `SELECT l.id, l.due_id, l.status, l.detail, l.created_at, cu.name as customer_name
     FROM fp_reminder_log l LEFT JOIN fp_expected_dues d ON d.id=l.due_id LEFT JOIN fp_customers cu ON cu.id=d.customer_id
     WHERE l.client_id=? ORDER BY l.id DESC LIMIT 100`
  ).bind(Number(payload.cid)).all();
  return json({list:results||[]});
}

// Month-end dashboard — one aggregate route (same "compute everything server-side, one response"
// shape as handleReportsProducts) rather than the frontend stitching several fetches together.
const FP_AGING_BUCKETS=[{key:'0-7',min:0,max:7},{key:'8-15',min:8,max:15},{key:'16-30',min:16,max:30},{key:'30+',min:31,max:Infinity}];
async function handleFpDashboard(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const now=new Date();
  const currentPeriod=now.toISOString().slice(0,7);
  const todayStr=now.toISOString().slice(0,10);

  const {results:dues}=await env.DB.prepare(`SELECT d.*, c.name as customer_name, c.phone as customer_phone FROM fp_expected_dues d JOIN fp_customers c ON c.id=d.customer_id WHERE d.client_id=?`).bind(clientId).all();
  const allDues=dues||[];
  const thisMonthDues=allDues.filter(d=>d.period_key===currentPeriod);
  const expectedThisMonth=thisMonthDues.reduce((s,d)=>s+d.amount,0);
  const collectedThisMonth=thisMonthDues.reduce((s,d)=>s+d.collected_amount,0);
  const collectionPct=expectedThisMonth>0?Math.round(collectedThisMonth/expectedThisMonth*1000)/10:0;

  const outstanding=allDues.filter(d=>d.status==='open'||d.status==='partial').map(d=>{
    const overdueDays=Math.max(0, Math.floor((now.getTime()-new Date(d.due_date).getTime())/86400000));
    const bucket=(FP_AGING_BUCKETS.find(b=>overdueDays>=b.min&&overdueDays<=b.max)||FP_AGING_BUCKETS[FP_AGING_BUCKETS.length-1]).key;
    return {Id:d.id, customer_id:d.customer_id, customer_name:d.customer_name, customer_phone:d.customer_phone,
      period_key:d.period_key, amount:d.amount, collected_amount:d.collected_amount, balance:Math.round((d.amount-d.collected_amount)*100)/100,
      currency:d.currency, due_date:d.due_date, overdue_days:d.due_date<todayStr?overdueDays:0, aging_bucket:d.due_date<todayStr?bucket:null, status:d.status};
  }).sort((a,b)=>b.overdue_days-a.overdue_days);

  const agingBuckets=FP_AGING_BUCKETS.map(b=>({
    key:b.key,
    count:outstanding.filter(o=>o.aging_bucket===b.key).length,
    amount:Math.round(outstanding.filter(o=>o.aging_bucket===b.key).reduce((s,o)=>s+o.balance,0)*100)/100,
  }));

  // Expenses — Financial Planning's own fp_expenses (fixed + one-time) AND the separate Expense
  // Entry tab's accounting_expenses, folded into one Total Expenses figure: two entry points into
  // the same "money going out" total, same interconnection as the receivables/payables below.
  const {results:expenses}=await env.DB.prepare(`SELECT * FROM fp_expenses WHERE client_id=? AND expense_date>=?`).bind(clientId, currentPeriod+'-01').all();
  const thisMonthExpenses=(expenses||[]).filter(e=>e.expense_date.slice(0,7)===currentPeriod);
  const fixedExpenseTotal=thisMonthExpenses.filter(e=>e.type==='fixed').reduce((s,e)=>s+e.amount,0);
  const onetimeExpenseTotal=thisMonthExpenses.filter(e=>e.type==='onetime').reduce((s,e)=>s+e.amount,0);
  const {results:acctExpenses}=await env.DB.prepare(`SELECT expense_date, amount FROM accounting_expenses WHERE client_id=? AND expense_date>=?`).bind(clientId, currentPeriod+'-01').all();
  const acctExpenseTotal=(acctExpenses||[]).filter(e=>e.expense_date.slice(0,7)===currentPeriod).reduce((s,e)=>s+e.amount,0);
  const totalExpenses=fixedExpenseTotal+onetimeExpenseTotal+acctExpenseTotal;
  const netPosition=Math.round((collectedThisMonth-totalExpenses)*100)/100;

  // Documents' unpaid invoices — ad-hoc/one-off billing (as opposed to fp_expected_dues' recurring
  // billing) folded into the same "Money Owed to You" the Dashboard already tracks, so Documents
  // and Financial Planning read as one business, not two separate receivables pictures.
  const {results:unpaidInvoices}=await env.DB.prepare(`SELECT * FROM accounting_documents WHERE client_id=? AND type='invoice' AND status IN ('draft','sent')`).bind(clientId).all();
  const invoiceReceivablesTotal=(unpaidInvoices||[]).reduce((s,d)=>s+(d.total||0),0);

  // Vendor Bills not yet paid — the accounts-payable counterpart, "Money You Owe". Aged the same
  // way outstanding receivables are (FP_AGING_BUCKETS against due_date vs. today).
  const {results:unpaidBillsRaw}=await env.DB.prepare(`SELECT * FROM accounting_vendor_bills WHERE client_id=? AND status!='paid'`).bind(clientId).all();
  const payables=(unpaidBillsRaw||[]).map(b=>{
    const isOverdue=!!(b.due_date && b.due_date<todayStr);
    const overdueDays=isOverdue?Math.max(0, Math.floor((now.getTime()-new Date(b.due_date).getTime())/86400000)):0;
    const bucket=isOverdue?(FP_AGING_BUCKETS.find(x=>overdueDays>=x.min&&overdueDays<=x.max)||FP_AGING_BUCKETS[FP_AGING_BUCKETS.length-1]).key:null;
    return {Id:b.id, supplier:b.supplier, bill_date:b.bill_date, due_date:b.due_date, total:b.total, currency:b.currency, overdue_days:overdueDays, aging_bucket:bucket};
  }).sort((a,b)=>b.overdue_days-a.overdue_days);
  const payablesTotal=Math.round(payables.reduce((s,p)=>s+p.total,0)*100)/100;

  // 6-month trend — expected/collected from fp_expected_dues, expenses from both fp_expenses and
  // accounting_expenses, keyed by the same 'YYYY-MM' period_key/expense_date-prefix convention
  // used throughout this module.
  const {results:allExpensesForTrend}=await env.DB.prepare(`SELECT expense_date, amount FROM fp_expenses WHERE client_id=?`).bind(clientId).all();
  const {results:allAcctExpensesForTrend}=await env.DB.prepare(`SELECT expense_date, amount FROM accounting_expenses WHERE client_id=?`).bind(clientId).all();
  const months=[];
  for(let i=5;i>=0;i--){ const d=new Date(now.getFullYear(), now.getMonth()-i, 1); months.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')); }
  const trend=months.map(m=>({
    period:m,
    expected:Math.round(allDues.filter(d=>d.period_key===m).reduce((s,d)=>s+d.amount,0)*100)/100,
    collected:Math.round(allDues.filter(d=>d.period_key===m).reduce((s,d)=>s+d.collected_amount,0)*100)/100,
    expenses:Math.round(
      ((allExpensesForTrend||[]).filter(e=>e.expense_date.slice(0,7)===m).reduce((s,e)=>s+e.amount,0)
      +(allAcctExpensesForTrend||[]).filter(e=>e.expense_date.slice(0,7)===m).reduce((s,e)=>s+e.amount,0))*100
    )/100,
  }));

  // Tax set-aside estimate — a plain `profit * tax_reserve_pct` nudge, nothing more (no bracket
  // logic, no jurisdiction awareness). Only shown when the owner has actually set a rate in
  // Settings AND this month is in profit — a negative net position has nothing to set aside, and
  // showing a 0 there would read as "you owe nothing" rather than "not applicable this month".
  const cfg=await env.DB.prepare(`SELECT tax_reserve_pct FROM fp_config WHERE client_id=?`).bind(clientId).first();
  const taxReservePct=cfg?.tax_reserve_pct;
  const estimatedTaxSetAside=(taxReservePct&&netPosition>0)?Math.round(netPosition*(taxReservePct/100)*100)/100:null;

  const currency=thisMonthDues[0]?.currency||allDues[0]?.currency||unpaidInvoices?.[0]?.currency||payables[0]?.currency||'INR';
  return json({
    currency, current_period:currentPeriod,
    expected_this_month:Math.round(expectedThisMonth*100)/100, collected_this_month:Math.round(collectedThisMonth*100)/100, collection_pct:collectionPct,
    fixed_expense_total:Math.round(fixedExpenseTotal*100)/100, onetime_expense_total:Math.round(onetimeExpenseTotal*100)/100,
    acct_expense_total:Math.round(acctExpenseTotal*100)/100, total_expenses:Math.round(totalExpenses*100)/100,
    net_position:netPosition, aging_buckets:agingBuckets, outstanding, trend,
    tax_reserve_pct:taxReservePct||null, estimated_tax_set_aside:estimatedTaxSetAside,
    // Unified receivables/payables — Documents' unpaid invoices folded into "Money Owed to You",
    // Vendor Bills' unpaid ones as "Money You Owe" (see the query comments above).
    invoice_receivables_total:Math.round(invoiceReceivablesTotal*100)/100, unpaid_invoice_count:(unpaidInvoices||[]).length,
    money_owed_to_you_total:Math.round((outstanding.reduce((s,o)=>s+o.balance,0)+invoiceReceivablesTotal)*100)/100,
    payables, payables_total:payablesTotal, unpaid_bill_count:payables.length,
  });
}

// ── Standard Accounting Reports (frontend/accounting.html "📊 Reports" tab) — computed on demand
// from the same tables the rest of the module already writes to (fp_expected_dues/fp_collections/
// fp_expenses, accounting_documents/accounting_expenses/accounting_vendor_bills). No new ledger,
// no double-entry — these are aggregate SQL reads over existing data, the same "compute
// everything server-side, one response" shape as handleFpDashboard.
function fpReportsDateRange(url){
  const now=new Date();
  const defaultFrom=new Date(now.getFullYear(), now.getMonth(), 1).toISOString().slice(0,10);
  const defaultTo=now.toISOString().slice(0,10);
  return {
    from:(url.searchParams.get('from')||defaultFrom).slice(0,10),
    to:(url.searchParams.get('to')||defaultTo).slice(0,10),
  };
}
// Profit & Loss — Income is actual money received (fp_collections + Documents' Receipts, both
// within range), not merely invoiced/expected, since a P&L should reflect cash actually earned;
// Expenses are fp_expenses + accounting_expenses within the same range.
async function handleFpReportPL(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const url=new URL(request.url);
  const {from, to}=fpReportsDateRange(url);
  const toExclusive=to+' 23:59:59';

  const {results:collections}=await env.DB.prepare(`SELECT amount, currency FROM fp_collections WHERE client_id=? AND collected_at>=? AND collected_at<=?`).bind(clientId, from, to).all();
  const {results:receipts}=await env.DB.prepare(`SELECT total, currency FROM accounting_documents WHERE client_id=? AND type='receipt' AND doc_created_at>=? AND doc_created_at<=?`).bind(clientId, from, toExclusive).all();
  const recurringIncome=(collections||[]).reduce((s,c)=>s+c.amount,0);
  const oneOffIncome=(receipts||[]).reduce((s,r)=>s+(r.total||0),0);
  const totalIncome=recurringIncome+oneOffIncome;

  const {results:fpExp}=await env.DB.prepare(`SELECT category, amount FROM fp_expenses WHERE client_id=? AND expense_date>=? AND expense_date<=?`).bind(clientId, from, to).all();
  const {results:acctExp}=await env.DB.prepare(`SELECT category, amount FROM accounting_expenses WHERE client_id=? AND expense_date>=? AND expense_date<=?`).bind(clientId, from, to).all();
  const allExpenseRows=[...(fpExp||[]), ...(acctExp||[])];
  const totalExpenses=allExpenseRows.reduce((s,e)=>s+e.amount,0);
  const byCategory={};
  for(const e of allExpenseRows){ const cat=e.category||'Uncategorized'; byCategory[cat]=(byCategory[cat]||0)+e.amount; }
  const expenseByCategory=Object.entries(byCategory).sort((a,b)=>b[1]-a[1]).map(([category,amount])=>({category, amount:Math.round(amount*100)/100}));

  const currency=collections?.[0]?.currency||receipts?.[0]?.currency||'INR';
  return json({
    from, to, currency,
    recurring_income:Math.round(recurringIncome*100)/100, one_off_income:Math.round(oneOffIncome*100)/100, total_income:Math.round(totalIncome*100)/100,
    total_expenses:Math.round(totalExpenses*100)/100, expense_by_category:expenseByCategory,
    net_profit:Math.round((totalIncome-totalExpenses)*100)/100,
  });
}
// Accounts Receivable Aging — Financial Planning's recurring Expected Funds (still open/partial)
// AND Documents' unpaid one-off invoices, in one aged list — the same unification
// handleFpDashboard's "Money Owed to You" uses, presented here as its own report with a
// per-bucket breakdown.
async function handleFpReportArAging(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const now=new Date(); const todayStr=now.toISOString().slice(0,10);
  const {results:dues}=await env.DB.prepare(`SELECT d.*, c.name as customer_name FROM fp_expected_dues d JOIN fp_customers c ON c.id=d.customer_id WHERE d.client_id=? AND d.status IN ('open','partial')`).bind(clientId).all();
  const {results:invoices}=await env.DB.prepare(`SELECT * FROM accounting_documents WHERE client_id=? AND type='invoice' AND status IN ('draft','sent')`).bind(clientId).all();
  const items=[
    ...(dues||[]).map(d=>({source:'recurring', name:d.customer_name, reference:d.period_key, date:d.due_date, balance:Math.round((d.amount-d.collected_amount)*100)/100, currency:d.currency})),
    ...(invoices||[]).map(d=>({source:'invoice', name:d.customer_name||'—', reference:'Invoice #'+d.id, date:d.doc_created_at?.slice(0,10)||todayStr, balance:d.total, currency:d.currency})),
  ].map(item=>{
    const overdueDays=Math.max(0, Math.floor((now.getTime()-new Date(item.date).getTime())/86400000));
    const isOverdue=item.date<todayStr;
    const bucket=isOverdue?(FP_AGING_BUCKETS.find(b=>overdueDays>=b.min&&overdueDays<=b.max)||FP_AGING_BUCKETS[FP_AGING_BUCKETS.length-1]).key:'not yet due';
    return {...item, overdue_days:isOverdue?overdueDays:0, aging_bucket:bucket};
  }).sort((a,b)=>b.overdue_days-a.overdue_days);
  const buckets=[...FP_AGING_BUCKETS.map(b=>b.key), 'not yet due'].map(key=>({
    key, count:items.filter(i=>i.aging_bucket===key).length,
    amount:Math.round(items.filter(i=>i.aging_bucket===key).reduce((s,i)=>s+i.balance,0)*100)/100,
  }));
  return json({items, buckets, total:Math.round(items.reduce((s,i)=>s+i.balance,0)*100)/100, currency:items[0]?.currency||'INR'});
}
// Accounts Payable Aging — Vendor Bills not yet paid, same bucket shape as AR aging above.
async function handleFpReportApAging(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const now=new Date(); const todayStr=now.toISOString().slice(0,10);
  const {results:bills}=await env.DB.prepare(`SELECT * FROM accounting_vendor_bills WHERE client_id=? AND status!='paid'`).bind(clientId).all();
  const items=(bills||[]).map(b=>{
    const dueDate=b.due_date||b.bill_date;
    const isOverdue=dueDate<todayStr;
    const overdueDays=Math.max(0, Math.floor((now.getTime()-new Date(dueDate).getTime())/86400000));
    const bucket=isOverdue?(FP_AGING_BUCKETS.find(x=>overdueDays>=x.min&&overdueDays<=x.max)||FP_AGING_BUCKETS[FP_AGING_BUCKETS.length-1]).key:'not yet due';
    return {Id:b.id, name:b.supplier, reference:b.vendor_invoice_no||('Bill #'+b.id), date:dueDate, balance:b.total, currency:b.currency, overdue_days:isOverdue?overdueDays:0, aging_bucket:bucket};
  }).sort((a,b)=>b.overdue_days-a.overdue_days);
  const buckets=[...FP_AGING_BUCKETS.map(b=>b.key), 'not yet due'].map(key=>({
    key, count:items.filter(i=>i.aging_bucket===key).length,
    amount:Math.round(items.filter(i=>i.aging_bucket===key).reduce((s,i)=>s+i.balance,0)*100)/100,
  }));
  return json({items, buckets, total:Math.round(items.reduce((s,i)=>s+i.balance,0)*100)/100, currency:items[0]?.currency||'INR'});
}
// Expense Breakdown — category totals across both expense sources over a trailing window
// (default 6 months), plus a month-by-month series per category's top contributors.
async function handleFpReportExpenseBreakdown(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const url=new URL(request.url);
  const months=Math.min(24, parseInt(url.searchParams.get('months'))||6);
  const since=new Date(); since.setMonth(since.getMonth()-(months-1)); since.setDate(1);
  const sinceStr=since.toISOString().slice(0,10);
  const {results:fpExp}=await env.DB.prepare(`SELECT category, amount, expense_date FROM fp_expenses WHERE client_id=? AND expense_date>=?`).bind(clientId, sinceStr).all();
  const {results:acctExp}=await env.DB.prepare(`SELECT category, amount, expense_date FROM accounting_expenses WHERE client_id=? AND expense_date>=?`).bind(clientId, sinceStr).all();
  const rows=[...(fpExp||[]), ...(acctExp||[])];
  const byCategory={};
  for(const e of rows){ const cat=e.category||'Uncategorized'; byCategory[cat]=(byCategory[cat]||0)+e.amount; }
  const categories=Object.entries(byCategory).sort((a,b)=>b[1]-a[1]).map(([category,amount])=>({category, amount:Math.round(amount*100)/100}));
  const total=rows.reduce((s,e)=>s+e.amount,0);
  return json({months, since:sinceStr, categories, total:Math.round(total*100)/100});
}
// Sales Summary — Documents (Quotation/Invoice/Receipt) counts and totals by type/status within a
// date range, plus a simple quotation→invoice conversion rate.
async function handleFpReportSalesSummary(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const url=new URL(request.url);
  const {from, to}=fpReportsDateRange(url);
  const toExclusive=to+' 23:59:59';
  const {results:docs}=await env.DB.prepare(`SELECT * FROM accounting_documents WHERE client_id=? AND doc_created_at>=? AND doc_created_at<=?`).bind(clientId, from, toExclusive).all();
  const rows=docs||[];
  const byType=['quotation','invoice','receipt'].map(type=>{
    const typeRows=rows.filter(d=>d.type===type);
    return {type, count:typeRows.length, total:Math.round(typeRows.reduce((s,d)=>s+(d.total||0),0)*100)/100};
  });
  const quotations=rows.filter(d=>d.type==='quotation');
  const acceptedQuotations=quotations.filter(d=>d.status==='accepted'||d.status==='paid');
  const conversionPct=quotations.length?Math.round(acceptedQuotations.length/quotations.length*1000)/10:null;
  const currency=rows[0]?.currency||'INR';
  return json({from, to, currency, by_type:byType, quotation_count:quotations.length, quotation_conversion_pct:conversionPct, total_documents:rows.length});
}

// ── Monthly generation cron — Expected Funds + fixed-recurring expenses ──
// Piggybacks on the existing daily '0 2 * * *' tick (see scheduled() below) rather than adding a
// new distinct cron string — the dispatcher's trailing `else` branch currently catches any cron
// string it doesn't explicitly match, so introducing a 4th string without also fixing that
// fallthrough risks silently misrouting an existing schedule. Self-gates on the UTC calendar date
// instead, same "day-granularity cadence doesn't need its own tick" reasoning as the Pipeline
// follow-up cadence's own comment in wrangler.toml.
async function runFinancialPlanningMonthlyForAllClients(env){
  if(new Date().getUTCDate()!==1) return;
  const {results:configs}=await env.DB.prepare(`SELECT client_id FROM fp_config WHERE enabled=1`).all();
  const periodKey=new Date().toISOString().slice(0,7);
  for(const cfg of (configs||[])){
    try{ await fpGenerateForClient(env, cfg.client_id, periodKey); }
    catch(e){ console.error('[financial-planning] monthly generation failed for client', cfg.client_id, e.message); }
  }
}
async function fpGenerateForClient(env, clientId, periodKey){
  const monthNum=Number(periodKey.slice(5,7));
  const now=new Date().toISOString();
  const {results:customers}=await env.DB.prepare(`SELECT * FROM fp_customers WHERE client_id=? AND status='active'`).bind(clientId).all();
  for(const cust of (customers||[])){
    // Quarterly/yearly customers only generate a due on the applicable months — monthly always
    // fires. A quarterly customer bills every Jan/Apr/Jul/Oct regardless of which of those months
    // they actually started in (simpler and more predictable than tracking an anniversary offset);
    // yearly bills only in their own start-month.
    if(cust.billing_cycle==='quarterly' && ![1,4,7,10].includes(monthNum)) continue;
    if(cust.billing_cycle==='yearly' && (new Date(cust.start_date).getUTCMonth()+1)!==monthNum) continue;
    const dueDate=`${periodKey}-${String(cust.billing_day).padStart(2,'0')}`;
    // A customer left at monthly_value=0 (e.g. just created, plan not set yet) has nothing
    // actually owed — seed the due as already 'paid' instead of 'open' so it never enters the
    // overdue-reminder sweep and gets chased for "0.00 due" (see fpSendRemindersForClient).
    const status=Number(cust.monthly_value)>0?'open':'paid';
    try{
      await env.DB.prepare(`INSERT INTO fp_expected_dues (client_id, customer_id, period_key, amount, currency, due_date, status, created_at) VALUES (?,?,?,?,?,?,?,?)`)
        .bind(clientId, cust.id, periodKey, cust.monthly_value, cust.currency, dueDate, status, now).run();
    }catch(e){ /* unique(customer_id, period_key) already hit — this period was already generated, harmless no-op */ }
  }
  const {results:templates}=await env.DB.prepare(`SELECT * FROM fp_expense_templates WHERE client_id=? AND active=1`).bind(clientId).all();
  for(const t of (templates||[])){
    try{
      await env.DB.prepare(`INSERT INTO fp_expenses (client_id, template_id, type, category, name, amount, currency, period_key, expense_date, created_at) VALUES (?,?,?,?,?,?,?,?,?,?)`)
        .bind(clientId, t.id, 'fixed', t.category, t.name, t.amount, t.currency, periodKey, `${periodKey}-01`, now).run();
    }catch(e){ /* unique(template_id, period_key) already hit — already booked this month */ }
  }
}

// ── AI-Supported Bookkeeping (Financial Planning) — layman-friendly SMB features built on the
// same shared Gemini integration the WhatsApp engine already uses (env.GEMINI_API_KEY,
// engineGeminiGenerate above) — no new provider/credential to configure. Three capabilities:
// (1) turn a plain-English sentence or a photo of a receipt into a structured fp_expenses draft
// the owner still reviews and saves themselves (never auto-saved — a misread amount silently
// posted would be worse than no AI at all); (2) "Ask Your Books", natural-language Q&A answered
// ONLY from real numbers computed here server-side, never left to the model to recall/estimate;
// (3) a cached one-paragraph monthly narrative snapshot (fp_config.ai_snapshot_period, migration
// 0034), computed once per calendar month rather than on every dashboard load.
const FP_EXPENSE_CATEGORIES=['Rent','Utilities','Salaries & Wages','Software & Subscriptions','Marketing & Ads','Travel','Office Supplies','Professional Fees','Bank Charges','Repairs & Maintenance','Inventory & Supplies','Taxes','Insurance','Miscellaneous'];

function fpAiNormalizeParsedExpense(parsed, defaultCurrency){
  if(!parsed || typeof parsed!=='object') return null;
  return {
    name:String(parsed.name||'').trim().slice(0,140)||'Expense',
    category:FP_EXPENSE_CATEGORIES.includes(parsed.category)?parsed.category:'Miscellaneous',
    vendor:String(parsed.vendor||'').trim().slice(0,140),
    amount:Number(parsed.amount)||0,
    currency:String(parsed.currency||defaultCurrency||'INR').trim().slice(0,10).toUpperCase(),
    expense_date:/^\d{4}-\d{2}-\d{2}$/.test(parsed.expense_date||'')?parsed.expense_date:new Date().toISOString().slice(0,10),
    notes:String(parsed.notes||'').trim().slice(0,500),
  };
}
async function fpAiParseExpenseText(env, text, defaultCurrency){
  if(!env.GEMINI_API_KEY || !text) return null;
  const today=new Date().toISOString().slice(0,10);
  const system=`You convert a small business owner's plain description of a purchase or expense into one structured bookkeeping record. They are not an accountant — never use accounting jargon back at them. Today's date is ${today}. Default currency is ${defaultCurrency} unless the text clearly states another. Respond with ONLY compact JSON, no commentary, in exactly this shape: {"name":"short title, 3-6 words","category":"one of: ${FP_EXPENSE_CATEGORIES.join(', ')}","vendor":"who was paid, or empty string","amount":number,"currency":"3-letter code","expense_date":"YYYY-MM-DD","notes":"anything extra worth keeping, or empty string"}. Resolve relative dates ("yesterday", "last Friday") against today's date. If you cannot tell the amount at all, set amount to 0.`;
  const raw=await engineGeminiGenerate(env, system, text, {temperature:0.1, maxOutputTokens:250, json:true});
  if(!raw) return null;
  try{ return fpAiNormalizeParsedExpense(JSON.parse(raw), defaultCurrency); }catch(e){ return null; }
}
async function fpAiParseExpenseImage(env, base64, mimeType, defaultCurrency){
  if(!env.GEMINI_API_KEY || !base64) return null;
  const today=new Date().toISOString().slice(0,10);
  const prompt=`This image is a photo of a receipt or bill for a small business expense. Today's date is ${today}. Read the vendor/merchant name, the total amount actually paid, and the date printed on it (if no date is visible, use today). Default currency is ${defaultCurrency} unless the receipt clearly shows another. Respond with ONLY compact JSON, no commentary, in exactly this shape: {"name":"short title, 3-6 words","category":"one of: ${FP_EXPENSE_CATEGORIES.join(', ')}","vendor":"merchant name, or empty string","amount":number,"currency":"3-letter code","expense_date":"YYYY-MM-DD","notes":"anything extra worth keeping, or empty string"}. If the total amount isn't legible, set amount to 0.`;
  try{
    const r=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${ENGINE_GEMINI_MODEL}:generateContent?key=${env.GEMINI_API_KEY}`, {
      method:'POST', headers:{'Content-Type':'application/json'},
      body:JSON.stringify({contents:[{role:'user', parts:[
        {text:prompt},
        {inline_data:{mime_type:mimeType||'image/jpeg', data:base64}}
      ]}], generationConfig:{temperature:0.1, maxOutputTokens:250, responseMimeType:'application/json'}})
    });
    if(!r.ok) return null;
    const data=await r.json().catch(()=>({}));
    const parts=data?.candidates?.[0]?.content?.parts||[];
    const outText=parts.map(p=>p.text||'').join('').trim();
    if(!outText) return null;
    return fpAiNormalizeParsedExpense(JSON.parse(outText), defaultCurrency);
  }catch(e){ return null; }
}
async function handleFpAiParseExpense(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.GEMINI_API_KEY) return json({error:'AI features are not configured for this deployment yet.'}, 503);
  const body=await request.json().catch(()=>({}));
  const clientId=Number(payload.cid);
  const cust=await env.DB.prepare(`SELECT currency FROM fp_customers WHERE client_id=? ORDER BY id DESC LIMIT 1`).bind(clientId).first();
  const defaultCurrency=cust?.currency||'INR';
  let parsed=null;
  if(body.imageBase64){
    if(String(body.imageBase64).length>20*1024*1024) return json({error:'Image is too large.'}, 400);
    parsed=await fpAiParseExpenseImage(env, body.imageBase64, body.mimeType, defaultCurrency);
  }else if(body.text){
    parsed=await fpAiParseExpenseText(env, String(body.text).slice(0,500), defaultCurrency);
  }else{
    return json({error:'text or imageBase64 required'}, 400);
  }
  if(!parsed) return json({error:"Couldn't make sense of that — try adding the amount and what it was for, or enter it manually below."}, 422);
  return json({parsed});
}

// Real numbers only — the same aggregates a human would read off the Dashboard, just compact
// enough to hand to the model as its entire universe of facts. Both "Ask Your Books" and the
// monthly narrative snapshot below build their prompt around this one function so the two features
// can never disagree with each other or with the Dashboard itself.
async function fpAiComputeSnapshotData(env, clientId){
  const now=new Date();
  const currentPeriod=now.toISOString().slice(0,7);
  const todayStr=now.toISOString().slice(0,10);
  const {results:dues}=await env.DB.prepare(`SELECT d.* FROM fp_expected_dues d WHERE d.client_id=?`).bind(clientId).all();
  const allDues=dues||[];
  const thisMonthDues=allDues.filter(d=>d.period_key===currentPeriod);
  const expected=thisMonthDues.reduce((s,d)=>s+d.amount,0);
  const collected=thisMonthDues.reduce((s,d)=>s+d.collected_amount,0);
  const outstanding=allDues.filter(d=>d.status==='open'||d.status==='partial');
  const outstandingTotal=outstanding.reduce((s,d)=>s+(d.amount-d.collected_amount),0);
  const overdueCount=outstanding.filter(d=>d.due_date<todayStr).length;

  const since=new Date(now.getFullYear(), now.getMonth()-2, 1).toISOString().slice(0,10);
  const {results:expenses}=await env.DB.prepare(`SELECT * FROM fp_expenses WHERE client_id=? AND expense_date>=?`).bind(clientId, since).all();
  const {results:acctExpenses}=await env.DB.prepare(`SELECT * FROM accounting_expenses WHERE client_id=? AND expense_date>=?`).bind(clientId, since).all();
  const thisMonthExpenses=(expenses||[]).filter(e=>e.expense_date.slice(0,7)===currentPeriod);
  const thisMonthAcctExpenses=(acctExpenses||[]).filter(e=>e.expense_date.slice(0,7)===currentPeriod);
  const totalExpensesThisMonth=thisMonthExpenses.reduce((s,e)=>s+e.amount,0)+thisMonthAcctExpenses.reduce((s,e)=>s+e.amount,0);
  const byCategory={};
  for(const e of [...thisMonthExpenses, ...thisMonthAcctExpenses]){ const cat=e.category||'Uncategorized'; byCategory[cat]=(byCategory[cat]||0)+e.amount; }
  const topCategories=Object.entries(byCategory).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([category,amount])=>({category, amount:Math.round(amount*100)/100}));

  // Documents' unpaid invoices (Money Owed to You) + Vendor Bills unpaid (Money You Owe) — same
  // unified receivables/payables handleFpDashboard computes, so Ask Your Books and the monthly
  // snapshot narrative describe the whole business, not just recurring billing.
  const {results:unpaidInvoices}=await env.DB.prepare(`SELECT total FROM accounting_documents WHERE client_id=? AND type='invoice' AND status IN ('draft','sent')`).bind(clientId).all();
  const invoiceReceivablesTotal=(unpaidInvoices||[]).reduce((s,d)=>s+(d.total||0),0);
  const {results:unpaidBills}=await env.DB.prepare(`SELECT total FROM accounting_vendor_bills WHERE client_id=? AND status!='paid'`).bind(clientId).all();
  const payablesTotal=(unpaidBills||[]).reduce((s,b)=>s+(b.total||0),0);

  const activeCustomers=await env.DB.prepare(`SELECT COUNT(*) as n FROM fp_customers WHERE client_id=? AND status='active'`).bind(clientId).first();
  const currency=thisMonthDues[0]?.currency||allDues[0]?.currency||thisMonthExpenses[0]?.currency||'INR';
  return {
    current_period:currentPeriod, currency,
    expected_this_month:Math.round(expected*100)/100, collected_this_month:Math.round(collected*100)/100,
    total_expenses_this_month:Math.round(totalExpensesThisMonth*100)/100,
    net_position_this_month:Math.round((collected-totalExpensesThisMonth)*100)/100,
    outstanding_total:Math.round(outstandingTotal*100)/100, overdue_customer_count:overdueCount,
    money_owed_to_you_total:Math.round((outstandingTotal+invoiceReceivablesTotal)*100)/100,
    unpaid_invoice_count:(unpaidInvoices||[]).length,
    money_you_owe_total:Math.round(payablesTotal*100)/100, unpaid_bill_count:(unpaidBills||[]).length,
    top_expense_categories_this_month:topCategories,
    active_customer_count:activeCustomers?.n||0,
  };
}
async function handleFpAiAsk(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.GEMINI_API_KEY) return json({error:'AI features are not configured for this deployment yet.'}, 503);
  const body=await request.json().catch(()=>({}));
  const question=String(body.question||'').trim().slice(0,300);
  if(!question) return json({error:'question required'}, 400);
  const data=await fpAiComputeSnapshotData(env, Number(payload.cid));
  const system=`You are a friendly bookkeeping assistant for a small business owner who has no accounting background. Answer their question using ONLY the JSON data below — never invent or estimate a number that isn't in it. If the data doesn't cover what they're asking, say so plainly and suggest what to check instead. Keep the answer to 2-4 short sentences, warm and jargon-free (say "money customers owe you" not "receivables", "profit" not "net position"). All amounts are in ${data.currency}.\n\nDATA: ${JSON.stringify(data)}`;
  const answer=await engineGeminiGenerate(env, system, question, {temperature:0.3, maxOutputTokens:220});
  if(!answer) return json({error:"Couldn't reach the AI assistant just now — try again in a moment."}, 502);
  return json({answer, data});
}

async function fpAiGenerateSnapshotNarrative(env, clientId){
  const data=await fpAiComputeSnapshotData(env, clientId);
  const system=`You are a friendly bookkeeping assistant writing a one-paragraph monthly business snapshot for a small business owner with no accounting background. Use ONLY the JSON data below — never invent numbers. Plain, warm, encouraging but honest tone; 3-5 short sentences; no jargon (say "money customers owe you" not "receivables", "profit" not "net position"). Mention: how much came in, how much went out, whether they're up or down, and the single biggest expense category if there is one. All amounts are in ${data.currency}.\n\nDATA: ${JSON.stringify(data)}`;
  const text=await engineGeminiGenerate(env, system, 'Write the snapshot now.', {temperature:0.4, maxOutputTokens:220});
  return {text, data};
}
async function fpAiGetOrRefreshSnapshot(env, clientId, force){
  const currentPeriod=new Date().toISOString().slice(0,7);
  const row=await env.DB.prepare(`SELECT ai_snapshot_text, ai_snapshot_period, ai_snapshot_generated_at FROM fp_config WHERE client_id=?`).bind(clientId).first();
  if(!force && row?.ai_snapshot_text && row.ai_snapshot_period===currentPeriod){
    return {snapshot:row.ai_snapshot_text, period:row.ai_snapshot_period, generated_at:row.ai_snapshot_generated_at, cached:true};
  }
  if(!env.GEMINI_API_KEY) return {snapshot:row?.ai_snapshot_text||null, period:row?.ai_snapshot_period||null, error:'AI features are not configured for this deployment yet.'};
  const {text}=await fpAiGenerateSnapshotNarrative(env, clientId);
  if(!text) return {snapshot:row?.ai_snapshot_text||null, period:row?.ai_snapshot_period||null, generated_at:row?.ai_snapshot_generated_at||null, error:"Couldn't generate a fresh snapshot just now — showing the last one.", cached:!!row?.ai_snapshot_text};
  const now=new Date().toISOString();
  await env.DB.prepare(`INSERT INTO fp_config (client_id, enabled, reminders_enabled, ai_snapshot_text, ai_snapshot_period, ai_snapshot_generated_at, updated_at) VALUES (?,1,1,?,?,?,?)
    ON CONFLICT(client_id) DO UPDATE SET ai_snapshot_text=excluded.ai_snapshot_text, ai_snapshot_period=excluded.ai_snapshot_period, ai_snapshot_generated_at=excluded.ai_snapshot_generated_at, updated_at=excluded.updated_at`)
    .bind(clientId, text, currentPeriod, now, now).run();
  return {snapshot:text, period:currentPeriod, generated_at:now, cached:false};
}
async function handleFpAiSnapshotGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  return json(await fpAiGetOrRefreshSnapshot(env, Number(payload.cid), false));
}
async function handleFpAiSnapshotRegenerate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  return json(await fpAiGetOrRefreshSnapshot(env, Number(payload.cid), true));
}

// ── Cash Flow Forecast — plain-English "what's coming in/out before month end" narrative. Built
// from the SAME two sources the monthly generation cron and dashboard already read (open
// fp_expected_dues due before the end of THIS calendar month, and active fp_expense_templates —
// exactly what fpGenerateForClient will book/has booked for this period), so the forecast can never
// promise a number the rest of the module doesn't also expect to actually land.
async function fpAiComputeForecastData(env, clientId){
  const now=new Date();
  const currentPeriod=now.toISOString().slice(0,7);
  const todayStr=now.toISOString().slice(0,10);
  const monthEnd=new Date(now.getFullYear(), now.getMonth()+1, 0).toISOString().slice(0,10);
  const {results:dues}=await env.DB.prepare(
    `SELECT d.*, c.name as customer_name FROM fp_expected_dues d JOIN fp_customers c ON c.id=d.customer_id
     WHERE d.client_id=? AND d.period_key=? AND d.status IN ('open','partial')`
  ).bind(clientId, currentPeriod).all();
  const upcoming=(dues||[]).filter(d=>d.due_date<=monthEnd);
  const upcomingTotal=upcoming.reduce((s,d)=>s+(d.amount-d.collected_amount),0);
  const overdueAlready=upcoming.filter(d=>d.due_date<todayStr).reduce((s,d)=>s+(d.amount-d.collected_amount),0);

  const {results:templates}=await env.DB.prepare(`SELECT * FROM fp_expense_templates WHERE client_id=? AND active=1`).bind(clientId).all();
  const {results:bookedFixed}=await env.DB.prepare(`SELECT template_id FROM fp_expenses WHERE client_id=? AND period_key=? AND type='fixed'`).bind(clientId, currentPeriod).all();
  const bookedIds=new Set((bookedFixed||[]).map(e=>e.template_id));
  const stillDueFixed=(templates||[]).filter(t=>!bookedIds.has(t.id));
  const fixedUpcomingTotal=stillDueFixed.reduce((s,t)=>s+t.amount,0);
  const alreadyBookedFixedTotal=(bookedFixed||[]).length ? (await env.DB.prepare(`SELECT COALESCE(SUM(amount),0) as total FROM fp_expenses WHERE client_id=? AND period_key=? AND type='fixed'`).bind(clientId, currentPeriod).first())?.total||0 : 0;

  const currency=upcoming[0]?.currency||templates?.[0]?.currency||'INR';
  return {
    current_period:currentPeriod, today:todayStr, month_end:monthEnd, currency,
    expected_to_collect_by_month_end:Math.round(upcomingTotal*100)/100,
    already_overdue_within_that:Math.round(overdueAlready*100)/100,
    fixed_expenses_still_to_go_out:Math.round(fixedUpcomingTotal*100)/100,
    fixed_expenses_already_booked_this_month:Math.round(alreadyBookedFixedTotal*100)/100,
    projected_net_by_month_end:Math.round((upcomingTotal-fixedUpcomingTotal)*100)/100,
  };
}
async function handleFpAiForecast(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const data=await fpAiComputeForecastData(env, clientId);
  if(!env.GEMINI_API_KEY) return json({forecast:null, data, error:'AI features are not configured for this deployment yet.'});
  const system=`You are a friendly bookkeeping assistant writing a short cash-flow outlook for a small business owner with no accounting background. Use ONLY the JSON data below — never invent numbers. Plain, warm, jargon-free (say "money still to come in" not "receivables", "bills still to pay" not "payables"), 2-4 short sentences, mention the money expected in before month end, what's still due to go out for fixed costs, and the rough net position that leaves. All amounts are in ${data.currency}.\n\nDATA: ${JSON.stringify(data)}`;
  const forecast=await engineGeminiGenerate(env, system, 'Write the forecast now.', {temperature:0.35, maxOutputTokens:200});
  return json({forecast, data});
}

// ── AI-drafted invoice chase reminders — a friendlier, tone-matched replacement for the fixed
// template fpSendRemindersForClient otherwise sends; falls back to that exact template (returned
// alongside as `fallback`) if Gemini is unavailable or the call fails, so the automatic sweep never
// goes silent just because AI generation had a bad moment.
function fpDefaultReminderText(due, balance){
  return `Hi ${due.customer_name||''}, this is a friendly reminder that ${due.currency} ${balance.toFixed(2)} is due for ${due.period_key}. Please let us know once it's settled — thank you! 🙏`;
}
async function fpAiDraftReminder(env, due){
  const balance=Math.round((due.amount-due.collected_amount)*100)/100;
  const fallback=fpDefaultReminderText(due, balance);
  if(!env.GEMINI_API_KEY) return fallback;
  const overdueDays=Math.max(0, Math.floor((Date.now()-new Date(due.due_date).getTime())/86400000));
  const system=`Write one short, warm WhatsApp message to a customer reminding them a payment is due. Not robotic or threatening — this is a small business owner following up personally. Use the customer's name naturally. 1-3 sentences, end with a light thank-you. No subject line, no signature block, plain message text only.`;
  const userPrompt=`Customer: ${due.customer_name||'the customer'}\nAmount due: ${due.currency} ${balance.toFixed(2)}\nBilling period: ${due.period_key}\nDays overdue: ${overdueDays>0?overdueDays:'not yet overdue, due soon'}`;
  const drafted=await engineGeminiGenerate(env, system, userPrompt, {temperature:0.6, maxOutputTokens:150});
  return drafted||fallback;
}
async function handleFpAiDraftReminder(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.due_id) return json({error:'due_id required'}, 400);
  const due=await env.DB.prepare(`SELECT d.*, c.name as customer_name FROM fp_expected_dues d JOIN fp_customers c ON c.id=d.customer_id WHERE d.id=?`).bind(Number(body.due_id)).first();
  if(!due || String(due.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  const draft=await fpAiDraftReminder(env, due);
  return json({draft});
}

// Lightweight, non-AI "this looks unusual" nudge — a plain average-vs-latest comparison per
// category, not a model call, so it's instant and costs nothing on every list load. Needs at least
// 3 onetime expenses already in the same category to have a baseline at all; flags anything more
// than 2.5x that baseline. Deliberately skips 'fixed' rows (auto-booked from a template every month
// at the same amount by design — never "unusual").
function fpAiFlagUnusualExpenses(rows){
  const byCategory={};
  for(const r of rows){ if(r.type!=='onetime') continue; (byCategory[r.category]=byCategory[r.category]||[]).push(r); }
  const avgByCategory={};
  for(const [cat, list] of Object.entries(byCategory)){
    if(list.length<3) continue;
    avgByCategory[cat]=list.reduce((s,r)=>s+r.amount,0)/list.length;
  }
  return rows.map(r=>{
    if(r.type!=='onetime') return r;
    const avg=avgByCategory[r.category];
    const isUnusual=!!(avg && r.amount>avg*2.5);
    return {...r, is_unusual:isUnusual, category_avg:avg?Math.round(avg*100)/100:null};
  });
}

// ── Admin-number WhatsApp bookkeeping shortcut ──────────────────────────────────────────────
// The SAME WhatsApp number/inbox this client's lead-gen bot runs on can double as a private
// "text your bookkeeper" line for the owner's own phone(s) (fp_config.admin_phone_numbers,
// migration 0034) — handleEngineWebhook diverts a message from one of these numbers here BEFORE
// any of the lead pipeline runs (state load, intent classification, LEADS upsert), so it can never
// create/touch a CRM lead or count toward lead-gen metrics. Only the last 10 digits are ever
// compared (fpNormalizePhoneTail) — WhatsApp/Chatwoot payloads aren't consistent about country-code
// formatting, and a stored "+971501234567" still needs to match an inbound "00971501234567".
function fpNormalizePhoneTail(raw){ return String(raw||'').replace(/[^0-9]/g,'').slice(-10); }
async function fpIsAdminPhone(env, clientId, phone){
  if(!phone) return false;
  const row=await env.DB.prepare(`SELECT admin_phone_numbers FROM fp_config WHERE client_id=?`).bind(clientId).first();
  const list=engineParseJsonField(row?.admin_phone_numbers, []);
  if(!Array.isArray(list) || !list.length) return false;
  const tail=fpNormalizePhoneTail(phone);
  return tail.length===10 && list.some(n=>fpNormalizePhoneTail(n)===tail);
}
// Supports three message shapes — a photo of a receipt (Snap & Save), a voice note, or plain text.
// Voice is transcribed first (engineGeminiTranscribeVoice, same as the customer-facing pipeline),
// then everything funnels into an "is this a question or an expense to log" split: a question
// ("how much do I owe", trailing '?', etc.) gets the same fpAiComputeSnapshotData-backed answer as
// the in-app Ask Your Books; anything else is treated as an expense to log and — unlike the in-app
// Snap & Save/Quick Add, which always leaves a draft for the owner to confirm in the UI — is booked
// immediately, since being on the admin allow-list at all IS the confirmation here.
async function fpHandleAdminWhatsappMessage(env, c, clientId, convId, mediaType, mediaUrl, text){
  let resolvedText=text;
  let imageParsed=null;
  const cust=await env.DB.prepare(`SELECT currency FROM fp_customers WHERE client_id=? ORDER BY id DESC LIMIT 1`).bind(clientId).first();
  const defaultCurrency=cust?.currency||'INR';

  if(mediaType==='voice' && mediaUrl){
    const audio=await engineFetchAudioBase64(env, mediaUrl);
    if(audio?.tooShort){ await engineSendChatwootReply(env, c, clientId, convId, "That voice note was too short to make out — could you resend it?"); return; }
    if(audio?.base64) resolvedText=await engineGeminiTranscribeVoice(env, audio.mimeType, audio.base64, c.language, c.client_name);
    if(!resolvedText){ await engineSendChatwootReply(env, c, clientId, convId, "Couldn't quite make that out — could you type it instead?"); return; }
  }else if(mediaType==='image' && mediaUrl){
    try{
      const imgR=await fetch(mediaUrl);
      if(imgR.ok){
        const mimeType=(imgR.headers.get('content-type')||'image/jpeg').split(';')[0].trim();
        const buf=await imgR.arrayBuffer();
        if(buf.byteLength<=15*1024*1024) imageParsed=await fpAiParseExpenseImage(env, engineArrayBufferToBase64(buf), mimeType, defaultCurrency);
      }
    }catch(e){}
    if(!imageParsed || !imageParsed.amount){ await engineSendChatwootReply(env, c, clientId, convId, "Couldn't read an amount off that photo — could you type the expense instead, e.g. \"paid 2000 for fuel\"?"); return; }
  }

  const trimmed=(resolvedText||'').trim();
  const looksLikeQuestion=/\?\s*$/.test(trimmed) || /^(how|what|am i|is my|show|list|do i)\b/i.test(trimmed);
  if(!imageParsed && looksLikeQuestion && trimmed){
    const data=await fpAiComputeSnapshotData(env, clientId);
    const system=`You are a friendly bookkeeping assistant replying over WhatsApp to a small business owner with no accounting background. Answer using ONLY the JSON data below — never invent or estimate a number that isn't in it. Keep it to 2-3 short sentences, warm and jargon-free (say "money customers owe you" not "receivables"). All amounts are in ${data.currency}.\n\nDATA: ${JSON.stringify(data)}`;
    const answer=await engineGeminiGenerate(env, system, trimmed, {temperature:0.3, maxOutputTokens:200});
    await engineSendChatwootReply(env, c, clientId, convId, answer||"Couldn't reach the AI assistant just now — try again in a moment.");
    return;
  }

  const parsed=imageParsed || (trimmed?await fpAiParseExpenseText(env, trimmed, defaultCurrency):null);
  if(!parsed || !parsed.amount){
    await engineSendChatwootReply(env, c, clientId, convId, "Couldn't catch an amount in that — try something like \"paid 3500 for electricity yesterday\", a voice note, or a photo of the receipt.");
    return;
  }
  const now=new Date().toISOString();
  await env.DB.prepare(`INSERT INTO fp_expenses (client_id, template_id, type, category, name, amount, currency, period_key, expense_date, notes, created_at) VALUES (?,NULL,'onetime',?,?,?,?,NULL,?,?,?)`)
    .bind(clientId, parsed.category, parsed.name, parsed.amount, parsed.currency, parsed.expense_date, parsed.vendor?`Vendor: ${parsed.vendor}`:'', now).run();
  await engineSendChatwootReply(env, c, clientId, convId, `✅ Logged: ${parsed.name} — ${parsed.currency} ${parsed.amount.toLocaleString()} (${parsed.category}) on ${parsed.expense_date}. Open the Accounting app to edit or delete this if anything's off.`);
}

// ── Overdue-payment reminder sweep — runs on the same daily tick (see scheduled() below), unlike
// the monthly generation above. Re-notifies at most once every 3 days per due (reminder_sent_at
// flag-and-check, same "flag-flip idempotency" idiom as sweepAbandonedShopifyCheckouts) rather
// than every single day, so an overdue customer isn't messaged daily. Reuses the linked lead's own
// Chatwoot ConversationID — a customer record with no linked lead (manually added, never a real
// WhatsApp lead) has no thread to send into and is silently skipped. ──
async function runFinancialPlanningRemindersForAllClients(env){
  const {results:configs}=await env.DB.prepare(`SELECT client_id FROM fp_config WHERE enabled=1 AND reminders_enabled=1`).all();
  for(const cfg of (configs||[])){
    try{ await fpSendRemindersForClient(env, cfg.client_id); }
    catch(e){ console.error('[financial-planning] reminder sweep failed for client', cfg.client_id, e.message); }
  }
}
// One row per reminder attempt — sent, failed, or skipped-and-why — so the sweep's previously
// silent catch(e){} can no longer swallow a failure with zero trace (see migration 0041).
async function fpLogReminderAttempt(env, clientId, dueId, status, detail){
  try{
    await env.DB.prepare(`INSERT INTO fp_reminder_log (client_id, due_id, status, detail, created_at) VALUES (?,?,?,?,?)`)
      .bind(clientId, dueId||null, status, detail?String(detail).slice(0,500):null, new Date().toISOString()).run();
  }catch(e){}
}
async function fpSendRemindersForClient(env, clientId){
  const c=await getClientById(env, clientId);
  if(!c?.chatwoot_base||!c?.chatwoot_account_id||!c?.chatwoot_token) return;
  const cfg=await env.DB.prepare(`SELECT reminder_template_name, reminder_template_category, reminder_template_language FROM fp_config WHERE client_id=?`).bind(clientId).first();
  const templateName=String(cfg?.reminder_template_name||'').trim();
  // This sweep only ever runs off the daily cron (see comment above runFinancialPlanningRemindersForAllClients
  // and the header comment on this function), never inside a customer-initiated 24h session window, so a
  // plain-text send is not viable here — only an approved WhatsApp template reliably reaches the customer.
  // Without one assigned, skip the whole client rather than repeatedly attempting sends that WhatsApp will
  // reject (previously: plain-text POSTs that failed silently, see the old catch(e){} this replaced).
  if(!templateName){
    await fpLogReminderAttempt(env, clientId, null, 'skipped_no_template', 'No WhatsApp reminder template assigned in Financial Planning Settings.');
    return;
  }
  const todayStr=new Date().toISOString().slice(0,10);
  const staleCutoff=new Date(Date.now()-3*86400000).toISOString();
  const {results:overdue}=await env.DB.prepare(
    `SELECT d.*, cu.name as customer_name, cu.lead_id FROM fp_expected_dues d JOIN fp_customers cu ON cu.id=d.customer_id
     WHERE d.client_id=? AND d.status IN ('open','partial') AND d.due_date<? AND (d.amount-d.collected_amount)>0.009 AND (d.reminder_sent_at IS NULL OR d.reminder_sent_at<?)`
  ).bind(clientId, todayStr, staleCutoff).all();
  for(const due of (overdue||[])){
    if(!due.lead_id){ await fpLogReminderAttempt(env, clientId, due.id, 'skipped_no_lead', 'Customer has no linked WhatsApp lead.'); continue; }
    let convId=null;
    try{
      const leadR=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records/${due.lead_id}?fields=ConversationID`);
      const lead=await leadR.json().catch(()=>null);
      convId=lead?.ConversationID||null;
    }catch(e){}
    if(!convId){ await fpLogReminderAttempt(env, clientId, due.id, 'skipped_no_conversation', 'No WhatsApp conversation found for this customer\'s lead.'); continue; }
    // AI-drafted, tone-matched reminder (fpAiDraftReminder) — falls back to the exact fixed
    // template text it always used before if Gemini is unavailable or the call fails, so this
    // sweep never goes silent just because generation had a bad moment. Sent as the sole {{1}}
    // variable of the assigned approved template (same single-variable shape as
    // sendFlowWhatsappTemplate), since WhatsApp requires an approved template outside the 24h window.
    const msg=await fpAiDraftReminder(env, due);
    try{
      const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {
        method:'POST', headers:{api_access_token:c.chatwoot_token, 'Content-Type':'application/json'},
        body:JSON.stringify({content:msg, message_type:'outgoing', private:false, template_params:{name:templateName, category:cfg.reminder_template_category||'MARKETING', language:cfg.reminder_template_language||'en', processed_params:{1:msg}}})
      });
      if(r.ok){
        await env.DB.prepare(`UPDATE fp_expected_dues SET reminder_sent_at=? WHERE id=?`).bind(new Date().toISOString(), due.id).run();
        await fpLogReminderAttempt(env, clientId, due.id, 'sent', null);
      }else{
        await fpLogReminderAttempt(env, clientId, due.id, 'failed', `Chatwoot send failed: HTTP ${r.status}`);
      }
    }catch(e){ await fpLogReminderAttempt(env, clientId, due.id, 'failed', e.message); }
    await new Promise(res=>setTimeout(res, 300)); // pacing, same spirit as recovery.js's SEND_DELAY_MS
  }
}

// ── Razorpay webhook — a Collection Entry created straight from a payment.captured event.
// Per-client credentials (razorpay_key_id/razorpay_key_secret/razorpay_webhook_secret on
// fp_config), same "plaintext-on-CLIENTS-style-row convention as wa_token/chatwoot_token
// elsewhere in this file — no dedicated secrets vault for per-client credentials anywhere in this
// codebase" reasoning as the ERPNext integration. clientId travels in the URL path itself
// (/financial/razorpay-webhook/<clientId>, same shape as /calcom/webhook/<clientId>) purely as a
// lookup key — the actual trust boundary is the HMAC signature below, verified against that
// specific client's own webhook secret, not the URL.
async function verifyRazorpaySignature(secret, rawBody, sigHeader){
  if(!sigHeader || !secret) return false;
  const key=await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const sig=await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(rawBody));
  const expected=hex(sig);
  if(expected.length!==sigHeader.length) return false;
  let diff=0; for(let i=0;i<expected.length;i++) diff|=expected.charCodeAt(i)^sigHeader.charCodeAt(i);
  return diff===0;
}
async function handleRazorpayWebhook(request, env, clientIdParam){
  const clientId=Number(clientIdParam);
  if(!clientId) return json({ok:true}); // no client to act on — ack so Razorpay doesn't keep retrying
  const cfg=await env.DB.prepare(`SELECT razorpay_webhook_secret FROM fp_config WHERE client_id=?`).bind(clientId).first();
  if(!cfg?.razorpay_webhook_secret) return json({ok:true}); // not connected — nothing configured to verify against
  const rawBody=await request.text();
  const valid=await verifyRazorpaySignature(cfg.razorpay_webhook_secret, rawBody, request.headers.get('X-Razorpay-Signature'));
  if(!valid) return json({error:'Invalid signature'}, 401);
  let data; try{ data=JSON.parse(rawBody); }catch(e){ return json({ok:true}); }
  if(data.event!=='payment.captured' && data.event!=='payment_link.paid') return json({ok:true}); // not a payment-received event — nothing to record
  const payment=data.payload?.payment?.entity || data.payload?.payment_link?.entity?.payments?.[0];
  if(!payment) return json({ok:true});
  const paymentId=payment.id||payment.payment_id;
  const amount=(Number(payment.amount)||0)/100; // Razorpay amounts are in the smallest currency unit (paise)
  const notes=payment.notes||data.payload?.payment_link?.entity?.notes||{};
  const customerId=notes.fp_customer_id ? Number(notes.fp_customer_id) : null;
  const dueId=notes.fp_expected_due_id ? Number(notes.fp_expected_due_id) : null;
  if(!customerId) return json({ok:true}); // no way to attribute this payment to a customer — nothing to record
  const cust=await findFpCustomer(env, customerId);
  if(!cust || cust.client_id!==clientId) return json({ok:true});
  const now=new Date().toISOString();
  try{
    const r=await env.DB.prepare(`INSERT INTO fp_collections (client_id, customer_id, expected_due_id, amount, currency, mode, razorpay_payment_id, collected_at, created_at) VALUES (?,?,?,?,?,?,?,?,?)`)
      .bind(clientId, customerId, dueId, amount, (payment.currency||cust.currency||'INR').toUpperCase(), 'razorpay', paymentId, now, now).run();
    if(dueId) await fpRecomputeDueStatus(env, dueId);
    return json({ok:true, collection_id:r.meta.last_row_id});
  }catch(e){
    // UNIQUE(razorpay_payment_id) collision — a redelivered webhook for a payment already recorded.
    return json({ok:true, duplicate:true});
  }
}

// ── SaaS Ops module (frontend/saas-ops.html — own top-level dashboard.html tab, shown only for
//    industry==='saas_digital_marketing'; SETUP.md "SaaS Ops module") ──
// v2 architecture: the client's OWN live NocoDB customers table (saas_config.nocodb_customers_
// table_id) is the Account system of record — NOT fp_customers (Financial Planning's own table,
// kept fully separate). saas_config/saas_collections/saas_unmatched_billing_events (migration 0027)
// replace fp_config/fp_expected_dues/fp_collections for this module. This app only ever writes
// `saas_`-prefixed columns it provisions itself onto the client's table (ensureSaasCustomerFields)
// — it never guesses at or overwrites a column the client already uses for their own purposes.
// ERPNext's role is narrowed to generating the actual invoice/quote documents (erpnextPushSalesDoc/
// erpnextPushPaymentEntry, reused unchanged) — not modeling who the customers are. Every
// frontend-facing route below follows this file's Financial Planning conventions (requireSession,
// row-ownership check against payload.cid); webhooks/usage ingestion use their own external auth
// instead, since no session exists on those calls.

const SAAS_LIFECYCLE_STAGES=new Set(['onboarding','active','at_risk','renewal','expansion','churned']);

// Shared HMAC primitive, same shape as verifyRazorpaySignature above.
async function hmacSha256Hex(secret, payload){
  const key=await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const sig=await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(payload));
  return hex(sig);
}
function timingSafeEqualStr(a, b){
  if(a.length!==b.length) return false;
  let diff=0; for(let i=0;i<a.length;i++) diff|=a.charCodeAt(i)^b.charCodeAt(i);
  return diff===0;
}
// None of the three signature verifiers below have been exercised against a live provider account
// in this session (no Stripe/Chargebee/Paddle test credentials exist here) — each is implemented
// to that provider's own publicly documented, stable scheme. Verify with a real test webhook
// (Stripe CLI's `stripe trigger`, Chargebee/Paddle's own webhook test-send) before relying on this.

// Stripe: `Stripe-Signature` header is `t=<unix ts>,v1=<hex hmac>[,v1=<hex hmac>...]` over the
// string `${ts}.${rawBody}` — https://docs.stripe.com/webhooks#verify-manually. Named distinctly
// from the existing verifyStripeSignature(env, rawBody, sigHeader) above (platform-level — verifies
// webhooks for THIS SaaS's own subscription billing via env.STRIPE_WEBHOOK_SECRET) — this one
// verifies a per-client's OWN Stripe account's webhooks against their own fp_config secret; same
// scheme, different secret source, so it can't reuse that function's signature.
async function verifySaasStripeSignature(secret, rawBody, sigHeader){
  if(!sigHeader || !secret) return false;
  const parts={}; sigHeader.split(',').forEach(p=>{ const [k,v]=p.split('='); if(k==='t') parts.t=v; else if(k==='v1' && !parts.v1) parts.v1=v; });
  if(!parts.t || !parts.v1) return false;
  const expected=await hmacSha256Hex(secret, `${parts.t}.${rawBody}`);
  return timingSafeEqualStr(expected, parts.v1);
}
// Chargebee doesn't HMAC-sign webhooks by default — its documented model is HTTP Basic Auth (or a
// shared token in the endpoint URL) configured on the webhook itself in the Chargebee dashboard —
// https://www.chargebee.com/docs/2.0/webhook_settings.html. `providedToken` is read from the URL
// path this webhook route registers (see route registration below), compared to the client's own
// chargebee_webhook_secret.
function verifyChargebeeToken(secret, providedToken){
  if(!secret || !providedToken) return false;
  return timingSafeEqualStr(secret, providedToken);
}
// Paddle (Billing API, not Classic): `Paddle-Signature` header is `ts=<unix ts>;h1=<hex hmac>`
// over `${ts}:${rawBody}` — https://developer.paddle.com/webhooks/signature-verification.
async function verifyPaddleSignature(secret, rawBody, sigHeader){
  if(!sigHeader || !secret) return false;
  const parts={}; sigHeader.split(';').forEach(p=>{ const [k,v]=p.split('='); parts[k]=v; });
  if(!parts.ts || !parts.h1) return false;
  const expected=await hmacSha256Hex(secret, `${parts.ts}:${rawBody}`);
  return timingSafeEqualStr(expected, parts.h1);
}

// ── NocoDB-as-account-store layer ───────────────────────────────────────────────────────────
// The client's OWN NocoDB customers table (saas_config.nocodb_customers_table_id) is the account
// system of record — not a D1 shadow table. We only ever WRITE to columns we create ourselves,
// all prefixed `saas_`, auto-provisioned below the same way ensureEcomProductStyleFields does for
// Ecommerce. We never guess at or overwrite a column the client already uses for their own data.
const SAAS_CUSTOMER_COMPUTED_FIELDS=['saas_lifecycle_stage','saas_health_score','saas_health_score_manual','saas_plan_tier','saas_plan_name','saas_monthly_value','saas_currency','saas_trial_end_date','saas_renewal_date','saas_seat_count','saas_csm_owner'];
const _saasCustomerFieldsEnsured=new Set();
async function ensureSaasCustomerFields(env, tableId){
  if(!tableId || _saasCustomerFieldsEnsured.has(tableId)) return;
  try{
    const existingR=await ncFetch(env, `api/v2/meta/tables/${tableId}/fields`);
    const existing=await existingR.json().catch(()=>({}));
    const names=new Set((existing.list||[]).map(f=>f.title));
    for(const title of SAAS_CUSTOMER_COMPUTED_FIELDS){
      if(!names.has(title)) await ncFetch(env, `api/v2/meta/tables/${tableId}/fields`, {method:'POST', body:{title, uidt:'SingleLineText'}});
    }
    _saasCustomerFieldsEnsured.add(tableId);
  }catch(e){ console.error('[saas-ops] ensureSaasCustomerFields failed', e.message); }
}

async function saasEnsureConfigRow(env, clientId){
  await env.DB.prepare(`INSERT INTO saas_config (client_id, updated_at) VALUES (?,?) ON CONFLICT(client_id) DO NOTHING`).bind(Number(clientId), new Date().toISOString()).run();
}

async function saasResolveCustomersTable(env, clientId){
  const cfg=await env.DB.prepare(`SELECT nocodb_customers_table_id FROM saas_config WHERE client_id=?`).bind(clientId).first();
  return (cfg?.nocodb_customers_table_id||'').trim()||null;
}

// Paginated full-row fetch (all columns, schema-agnostic) — same approach as the earlier
// NocoDB-import feature's fetch loop, promoted here into a shared helper.
async function saasFetchAllCustomers(env, tableId){
  let rows=[];
  for(let page=1; page<=20; page++){
    const r=await ncFetch(env, `api/v2/tables/${tableId}/records?limit=200&offset=${(page-1)*200}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const list=data?.list||[];
    rows=rows.concat(list);
    if(list.length<200) break;
  }
  return rows;
}

async function saasFetchCustomerById(env, tableId, id){
  const r=await ncFetch(env, `api/v2/tables/${tableId}/records/${id}`);
  if(!r.ok) return null;
  return await r.json().catch(()=>null);
}

async function saasWriteCustomerFields(env, tableId, rowId, fields){
  await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'PATCH', body:{Id:Number(rowId), ...fields}});
}

// Column-name aliases for the logical fields we need to read off an arbitrary client-owned table —
// reused from the earlier NocoDB-import feature (SAAS_NOCODB_IMPORT_FIELD_ALIASES), now used both
// for reading a value (saasGetCustomerField) and for resolving the real column name that means
// "email"/"phone" so we can build a NocoDB where= filter (saasResolveColumnName).
const SAAS_CUSTOMER_FIELD_ALIASES={
  name:['name','customername','customer','company','companyname','fullname','client','clientname','account','accountname'],
  email:['email','emailaddress','contactemail','billingemail','customeremail'],
  phone:['phone','phonenumber','mobile','mobilenumber','contactnumber','whatsapp','whatsappnumber','contact'],
  startDate:['startdate','signupdate','joindate','createdat','createddate','onboardeddate','subscriptionstart'],
};

function saasGetCustomerField(row, aliases){
  if(!row) return null;
  const keys=Object.keys(row);
  for(const alias of aliases){
    const norm=alias.replace(/[^a-z0-9]/g,'');
    const hit=keys.find(k=>k.toLowerCase().replace(/[^a-z0-9]/g,'')===norm);
    if(hit && row[hit]!=null && row[hit]!=='') return row[hit];
  }
  return null;
}
// Sibling of saasGetCustomerField — returns the matched COLUMN NAME instead of a value, for
// building where= filters. Scans a small sample of rows since a column present-but-blank on row 1
// shouldn't cause a false miss.
function saasResolveColumnName(rows, aliases){
  for(const row of rows){
    const keys=Object.keys(row);
    for(const alias of aliases){
      const norm=alias.replace(/[^a-z0-9]/g,'');
      const hit=keys.find(k=>k.toLowerCase().replace(/[^a-z0-9]/g,'')===norm);
      if(hit) return hit;
    }
  }
  return null;
}
const _saasColumnNameCache=new Map(); // tableId -> {name, email, phone, startDate}
async function saasResolveColumnNames(env, tableId){
  if(_saasColumnNameCache.has(tableId)) return _saasColumnNameCache.get(tableId);
  const r=await ncFetch(env, `api/v2/tables/${tableId}/records?limit=5`);
  const data=await r.json().catch(()=>({}));
  const rows=data?.list||[];
  const resolved={};
  if(rows.length){
    for(const field of Object.keys(SAAS_CUSTOMER_FIELD_ALIASES)) resolved[field]=saasResolveColumnName(rows, SAAS_CUSTOMER_FIELD_ALIASES[field]);
  }
  _saasColumnNameCache.set(tableId, resolved);
  return resolved;
}

// Matches a billing webhook event to a real NocoDB customer row by email (then phone). Never
// creates a row on a miss — callers fall back to saas_unmatched_billing_events instead.
async function saasFindCustomerByEmailOrPhone(env, tableId, email, phone){
  const cols=await saasResolveColumnNames(env, tableId);
  if(email && cols.email){
    const r=await ncFetch(env, `api/v2/tables/${tableId}/records?where=${encodeURIComponent(`(${cols.email},eq,${ecomSanitizeFilterValue(email)})`)}&limit=1`);
    const data=await r.json().catch(()=>({}));
    if(data?.list?.[0]) return data.list[0];
  }
  if(phone && cols.phone){
    const r=await ncFetch(env, `api/v2/tables/${tableId}/records?where=${encodeURIComponent(`(${cols.phone},eq,${ecomSanitizeFilterValue(phone)})`)}&limit=1`);
    const data=await r.json().catch(()=>({}));
    if(data?.list?.[0]) return data.list[0];
  }
  return null;
}

// Resolves a Chatwoot conversation for messaging (reminders, digests) by phone — replaces the old
// cust.lead_id chain, since a bare NocoDB customer row has no lead_id.
async function saasFindLeadConversationByPhone(env, clientId, phone){
  if(!phone) return null;
  const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(`(ClientId,eq,${clientId})~and(Phone,eq,${ecomSanitizeFilterValue(phone)})`)}&fields=ConversationID&limit=1`);
  const data=await r.json().catch(()=>({}));
  return data?.list?.[0]?.ConversationID||null;
}

// Normalized billing event applied to the client's NocoDB customers table + saas_collections — the
// 3 webhook handlers below each parse their own provider's payload into this one shape, so the
// actual matching/lifecycle/ERPNext-bridge logic exists exactly once instead of duplicated 3 times.
// action: 'subscription_active' | 'payment_succeeded' | 'subscription_cancelled'
async function saasApplyBillingEvent(env, clientId, {customerEmail, customerName, planName, amount, currency, action, occurredAt}){
  const now=new Date().toISOString();
  occurredAt=occurredAt||now;

  const recordUnmatched=async()=>{
    await env.DB.prepare(`INSERT INTO saas_unmatched_billing_events (client_id, source, action, customer_email, customer_name, plan_name, amount, currency, raw_payload, occurred_at, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?)`)
      .bind(clientId, 'webhook', action, customerEmail||'', customerName||'', planName||'', amount||0, currency||'', '', occurredAt, now).run();
  };

  const tableId=await saasResolveCustomersTable(env, clientId);
  if(!tableId){ await recordUnmatched(); return null; }

  const custRow=await saasFindCustomerByEmailOrPhone(env, tableId, customerEmail, null);
  if(!custRow){ await recordUnmatched(); return null; }

  await ensureSaasCustomerFields(env, tableId);
  const custId=custRow.Id;
  const custName=saasGetCustomerField(custRow, SAAS_CUSTOMER_FIELD_ALIASES.name)||customerName||customerEmail||'Customer';

  if(action==='subscription_active'){
    const wasChurned=custRow.saas_lifecycle_stage==='churned';
    await saasWriteCustomerFields(env, tableId, custId, {
      saas_lifecycle_stage: (custRow.saas_lifecycle_stage==='churned'||!custRow.saas_lifecycle_stage)?'active':custRow.saas_lifecycle_stage,
      saas_plan_name: planName||custRow.saas_plan_name||'',
      saas_monthly_value: String(amount||custRow.saas_monthly_value||0),
    });
    // Re-enable the ERPNext Customer record on reactivation — best-effort, only if one was ever
    // synced (a brand-new account has nothing to re-enable yet; erpnextPushSalesDoc below will
    // resolve/create it on the first payment either way).
    if(wasChurned){
      const c=await getClientById(env, clientId);
      if(c && erpnextConfigured(c)){
        try{ const erpCust=await erpnextFindCustomer(c, custName); if(erpCust) await erpnextSetCustomerDisabled(c, erpCust, false); }
        catch(e){ await reportOpsError(env, 'saasApplyBillingEvent — ERPNext re-enable failed', e, {clientId, customerId:custId}); }
      }
    }
  }else if(action==='subscription_cancelled'){
    await saasWriteCustomerFields(env, tableId, custId, {saas_lifecycle_stage:'churned'});
    // Disable (not delete) the matching ERPNext Customer — keeps their own sales/accounting team
    // from seeing a churned account as active in ERPNext's own UI, without touching the customer's
    // invoice/payment history there.
    const c=await getClientById(env, clientId);
    if(c && erpnextConfigured(c)){
      try{ const erpCust=await erpnextFindCustomer(c, custName); if(erpCust) await erpnextSetCustomerDisabled(c, erpCust, true); }
      catch(e){ await reportOpsError(env, 'saasApplyBillingEvent — ERPNext disable failed', e, {clientId, customerId:custId}); }
    }
  }else if(action==='payment_succeeded'){
    const periodKey=occurredAt.slice(0,7);
    const cur=currency||custRow.saas_currency||'USD';
    await env.DB.prepare(`INSERT INTO saas_collections (client_id, nocodb_customer_id, amount, currency, source, occurred_at, created_at) VALUES (?,?,?,?,?,?,?)`)
      .bind(clientId, String(custId), amount||0, cur, 'webhook', occurredAt, now).run();
    if(custRow.saas_lifecycle_stage==='onboarding' || custRow.saas_lifecycle_stage==='at_risk' || !custRow.saas_lifecycle_stage){
      await saasWriteCustomerFields(env, tableId, custId, {saas_lifecycle_stage:'active'});
    }

    // Bridge to the existing Accounting/ERPNext module — a real invoice + payment in the client's
    // own ERPNext, through the sync functions that already work (erpnextPushSalesDoc/
    // erpnextPushPaymentEntry) rather than a second, parallel invoicing concept. No fp_customers/
    // Lead chain exists here anymore, so a synthetic {Name, Phone} object stands in for a Lead —
    // erpnextResolveCustomer only ever reads .Name/.Phone off it.
    const c=await getClientById(env, clientId);
    if(c && erpnextConfigured(c)){
      try{
        const title=`${planName||custRow.saas_plan_name||'Subscription'} — ${periodKey}`;
        const lineItemsJson=JSON.stringify([{name:planName||custRow.saas_plan_name||'Subscription', qty:1, price:amount||0}]);
        const docR=await env.DB.prepare(`INSERT INTO accounting_documents (client_id, lead_id, type, title, line_items_json, currency, subtotal, tax_pct, tax_amount, total, status, doc_created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`)
          .bind(clientId, null, 'invoice', title, lineItemsJson, cur, amount||0, 0, 0, amount||0, 'paid', now).run();
        const doc=await findAccountingDocument(env, docR.meta.last_row_id);
        const fakeLead={Name:custName, Phone:saasGetCustomerField(custRow, SAAS_CUSTOMER_FIELD_ALIASES.phone)||''};
        const erpName=await erpnextPushSalesDoc(c, 'Sales Invoice', doc, fakeLead);
        await env.DB.prepare(`UPDATE accounting_documents SET erpnext_doctype='Sales Invoice', erpnext_doc_name=?, erpnext_sync_status='synced', erpnext_synced_at=? WHERE id=?`).bind(erpName||'', now, doc.id).run();
        const paymentErpName=await erpnextPushPaymentEntry(c, doc, fakeLead, erpName);
        // Auto-submit — a webhook-driven charge has no human in the loop to click "Publish" the way
        // the manual Quote/Invoice flow does, so a Draft here would just sit unposted in the
        // client's ERPNext ledger forever. Best-effort: if either submit fails (e.g. a mandatory
        // field Frappe requires isn't set), the document still exists as a correct, reviewable Draft
        // — this only ever upgrades a Draft to Submitted, never blocks the sync itself.
        try{
          if(erpName) await erpnextSubmitDocByName(c, 'Sales Invoice', erpName);
          if(paymentErpName) await erpnextSubmitDocByName(c, 'Payment Entry', paymentErpName);
          await env.DB.prepare(`UPDATE accounting_documents SET erpnext_submitted_at=? WHERE id=?`).bind(new Date().toISOString(), doc.id).run();
        }catch(submitErr){
          await reportOpsError(env, 'saasApplyBillingEvent — ERPNext auto-submit failed (doc still synced as Draft)', submitErr, {clientId, customerId:custId, docId:doc.id});
        }
      }catch(e){
        await reportOpsError(env, 'saasApplyBillingEvent — ERPNext bridge failed', e, {clientId, customerId:custId});
      }
    }
  }
  return custRow;
}

// clientId travels in the URL path (/saas/webhooks/stripe/<clientId> etc.), same lookup-key-only
// role as Razorpay's own webhook route above — the real trust boundary is the signature/token
// check against that specific client's own saas_config secret, not the URL.
async function handleSaasStripeWebhook(request, env, clientIdParam){
  const clientId=Number(clientIdParam);
  if(!clientId) return json({ok:true});
  const cfg=await env.DB.prepare(`SELECT stripe_webhook_secret FROM saas_config WHERE client_id=?`).bind(clientId).first();
  if(!cfg?.stripe_webhook_secret) return json({ok:true});
  const rawBody=await request.text();
  const valid=await verifySaasStripeSignature(cfg.stripe_webhook_secret, rawBody, request.headers.get('Stripe-Signature'));
  if(!valid) return json({error:'Invalid signature'}, 401);
  let evt; try{ evt=JSON.parse(rawBody); }catch(e){ return json({ok:true}); }
  const obj=evt.data?.object||{};
  try{
    if(evt.type==='customer.subscription.created' || evt.type==='customer.subscription.updated'){
      if(obj.status==='canceled'){
        await saasApplyBillingEvent(env, clientId, {customerEmail:obj.customer_email, action:'subscription_cancelled'});
      }else{
        await saasApplyBillingEvent(env, clientId, {
          customerEmail:obj.customer_email||obj.customer?.email, customerName:obj.customer?.name,
          planName:obj.items?.data?.[0]?.price?.nickname||obj.plan?.nickname,
          amount:(Number(obj.items?.data?.[0]?.price?.unit_amount)||0)/100, currency:(obj.currency||'usd').toUpperCase(),
          action:'subscription_active', occurredAt:new Date().toISOString(),
        });
      }
    }else if(evt.type==='customer.subscription.deleted'){
      await saasApplyBillingEvent(env, clientId, {customerEmail:obj.customer_email, action:'subscription_cancelled'});
    }else if(evt.type==='invoice.paid' || evt.type==='invoice.payment_succeeded'){
      await saasApplyBillingEvent(env, clientId, {
        customerEmail:obj.customer_email, customerName:obj.customer_name,
        planName:obj.lines?.data?.[0]?.description, amount:(Number(obj.amount_paid)||0)/100, currency:(obj.currency||'usd').toUpperCase(),
        action:'payment_succeeded', occurredAt:new Date((obj.status_transitions?.paid_at||obj.created)*1000).toISOString(),
      });
    }
  }catch(e){ await reportOpsError(env, 'handleSaasStripeWebhook', e, {clientId, type:evt.type}); }
  return json({ok:true});
}

async function handleSaasChargebeeWebhook(request, env, clientIdParam){
  const clientId=Number(clientIdParam);
  if(!clientId) return json({ok:true});
  const cfg=await env.DB.prepare(`SELECT chargebee_webhook_secret FROM saas_config WHERE client_id=?`).bind(clientId).first();
  if(!cfg?.chargebee_webhook_secret) return json({ok:true});
  const url=new URL(request.url);
  if(!verifyChargebeeToken(cfg.chargebee_webhook_secret, url.searchParams.get('token'))) return json({error:'Invalid token'}, 401);
  let evt; try{ evt=JSON.parse(await request.text()); }catch(e){ return json({ok:true}); }
  const sub=evt.content?.subscription||{};
  const cust=evt.content?.customer||{};
  const invoice=evt.content?.invoice||{};
  try{
    if(evt.event_type==='subscription_activated' || evt.event_type==='subscription_renewed'){
      await saasApplyBillingEvent(env, clientId, {
        customerEmail:cust.email, customerName:cust.first_name?`${cust.first_name} ${cust.last_name||''}`.trim():cust.company,
        planName:sub.plan_id, amount:(Number(sub.plan_unit_price)||0)/100, currency:sub.currency_code||'USD',
        action:'subscription_active', occurredAt:new Date().toISOString(),
      });
    }else if(evt.event_type==='subscription_cancelled'){
      await saasApplyBillingEvent(env, clientId, {customerEmail:cust.email, action:'subscription_cancelled'});
    }else if(evt.event_type==='payment_succeeded' || evt.event_type==='invoice_generated'){
      await saasApplyBillingEvent(env, clientId, {
        customerEmail:cust.email, customerName:cust.first_name?`${cust.first_name} ${cust.last_name||''}`.trim():cust.company,
        planName:sub.plan_id, amount:(Number(invoice.total)||0)/100, currency:invoice.currency_code||'USD',
        action:'payment_succeeded', occurredAt:new Date((invoice.date||Date.now()/1000)*1000).toISOString(),
      });
    }
  }catch(e){ await reportOpsError(env, 'handleSaasChargebeeWebhook', e, {clientId, type:evt.event_type}); }
  return json({ok:true});
}

async function handleSaasPaddleWebhook(request, env, clientIdParam){
  const clientId=Number(clientIdParam);
  if(!clientId) return json({ok:true});
  const cfg=await env.DB.prepare(`SELECT paddle_webhook_secret FROM saas_config WHERE client_id=?`).bind(clientId).first();
  if(!cfg?.paddle_webhook_secret) return json({ok:true});
  const rawBody=await request.text();
  const valid=await verifyPaddleSignature(cfg.paddle_webhook_secret, rawBody, request.headers.get('Paddle-Signature'));
  if(!valid) return json({error:'Invalid signature'}, 401);
  let evt; try{ evt=JSON.parse(rawBody); }catch(e){ return json({ok:true}); }
  const d=evt.data||{};
  try{
    if(evt.event_type==='subscription.activated' || evt.event_type==='subscription.updated'){
      if(d.status==='canceled'){
        await saasApplyBillingEvent(env, clientId, {customerEmail:d.customer?.email, action:'subscription_cancelled'});
      }else{
        await saasApplyBillingEvent(env, clientId, {
          customerEmail:d.customer?.email, customerName:d.customer?.name,
          planName:d.items?.[0]?.price?.name, amount:(Number(d.items?.[0]?.price?.unit_price?.amount)||0)/100, currency:d.currency_code||'USD',
          action:'subscription_active', occurredAt:new Date().toISOString(),
        });
      }
    }else if(evt.event_type==='subscription.canceled'){
      await saasApplyBillingEvent(env, clientId, {customerEmail:d.customer?.email, action:'subscription_cancelled'});
    }else if(evt.event_type==='transaction.completed'){
      await saasApplyBillingEvent(env, clientId, {
        customerEmail:d.customer?.email, customerName:d.customer?.name,
        planName:d.items?.[0]?.price?.name, amount:(Number(d.details?.totals?.total)||0)/100, currency:d.currency_code||'USD',
        action:'payment_succeeded', occurredAt:new Date(d.billed_at||Date.now()).toISOString(),
      });
    }
  }catch(e){ await reportOpsError(env, 'handleSaasPaddleWebhook', e, {clientId, type:evt.event_type}); }
  return json({ok:true});
}

// ── Usage / PQL ingestion — bearer-token-per-client (saas_config.usage_ingest_token, generated on
// first Integrations-tab load, see handleSaasConfigGet below), the client's own product calls this
// from its own backend on real usage events. Not session-gated — this is a server-to-server call
// from the client's own SaaS product, which has no Leadvyne session.
async function handleSaasUsageEvent(request, env){
  const auth=(request.headers.get('Authorization')||'').replace(/^Bearer\s+/i,'').trim();
  if(!auth) return json({error:'Missing bearer token'}, 401);
  const cfg=await env.DB.prepare(`SELECT client_id FROM saas_config WHERE usage_ingest_token=?`).bind(auth).first();
  if(!cfg) return json({error:'Invalid token'}, 401);
  const body=await request.json().catch(()=>({}));
  const customerId=parseInt(body.customer_id,10);
  if(!customerId || !body.event_name) return json({error:'customer_id and event_name required'}, 400);
  const now=new Date().toISOString();
  await env.DB.prepare(`INSERT INTO saas_usage_events (client_id, customer_id, event_name, event_count, occurred_at, created_at) VALUES (?,?,?,?,?,?)`)
    .bind(cfg.client_id, customerId, String(body.event_name).slice(0,100), parseInt(body.event_count,10)||1, body.occurred_at||now, now).run();
  return json({ok:true});
}
// Read side for the ingestion above — GET /saas/usage-events, the 🚀 SaaS Ops → Usage sub-tab.
// Was write-only until now (nothing surfaced what actually landed from a client's own product
// backend). Returns both a recent raw log (capped, most-recent-first) and a 30-day per-account/
// per-event-name summary — computed here rather than client-side since saas_usage_events can grow
// large and the summary aggregation is cheap to do once in SQL vs. shipping every row to the
// browser to group there.
async function handleSaasUsageEventsList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const url=new URL(request.url);
  const customerId=url.searchParams.get('customer_id');
  let recentSql=`SELECT * FROM saas_usage_events WHERE client_id=?`; const recentBinds=[clientId];
  if(customerId){ recentSql+=` AND customer_id=?`; recentBinds.push(Number(customerId)); }
  recentSql+=` ORDER BY occurred_at DESC LIMIT 300`;
  const {results:recent}=await env.DB.prepare(recentSql).bind(...recentBinds).all();

  const since=new Date(Date.now()-30*86400000).toISOString();
  let summarySql=`SELECT customer_id, event_name, SUM(event_count) total, COUNT(*) events, MAX(occurred_at) last_seen FROM saas_usage_events WHERE client_id=? AND occurred_at>=?`;
  const summaryBinds=[clientId, since];
  if(customerId){ summarySql+=` AND customer_id=?`; summaryBinds.push(Number(customerId)); }
  summarySql+=` GROUP BY customer_id, event_name ORDER BY total DESC LIMIT 200`;
  const {results:summary}=await env.DB.prepare(summarySql).bind(...summaryBinds).all();

  return json({list:(recent||[]).map(r=>({...r, Id:r.id})), summary_30d:summary||[]});
}

