// ── SaaS Ops config — Integrations sub-view of accounting.html's new tab. Same paste-in-your-own-
// key pattern as accounting.html's own ERPNext settings fields; usage_ingest_token is generated
// once and shown for the client to paste into their own product's backend.
async function handleSaasConfigGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  await saasEnsureConfigRow(env, payload.cid);
  let cfg=await env.DB.prepare(`SELECT * FROM saas_config WHERE client_id=?`).bind(Number(payload.cid)).first();
  if(!cfg.usage_ingest_token){
    const token=crypto.randomUUID().replace(/-/g,'');
    await env.DB.prepare(`UPDATE saas_config SET usage_ingest_token=? WHERE client_id=?`).bind(token, Number(payload.cid)).run();
    cfg=await env.DB.prepare(`SELECT * FROM saas_config WHERE client_id=?`).bind(Number(payload.cid)).first();
  }
  // Secrets are write-only from the browser's perspective past initial save — never echo a stored
  // secret back, same "never reaches the browser" convention as shopify_access_token/erpnext_api_secret.
  const {stripe_secret_key, chargebee_api_key, paddle_api_key, support_api_key, chargebee_webhook_secret, paddle_webhook_secret, stripe_webhook_secret, ...safe}=cfg;
  return json({...safe,
    stripe_connected:!!stripe_secret_key, chargebee_connected:!!chargebee_api_key, paddle_connected:!!paddle_api_key, support_connected:!!support_api_key,
  });
}
async function handleSaasConfigUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  await saasEnsureConfigRow(env, payload.cid);
  const body=await request.json().catch(()=>({}));
  const sets=[], vals=[];
  for(const f of ['stripe_secret_key','stripe_webhook_secret','chargebee_site','chargebee_api_key','chargebee_webhook_secret','paddle_api_key','paddle_webhook_secret','support_provider','support_api_key','support_subdomain','nocodb_customers_table_id']){
    if(body[f]!==undefined && body[f]!==''){ sets.push(`${f}=?`); vals.push(String(body[f]).trim().slice(0,500)); }
  }
  if(!sets.length) return json({ok:true});
  sets.push('updated_at=?'); vals.push(new Date().toISOString());
  vals.push(Number(payload.cid));
  await env.DB.prepare(`UPDATE saas_config SET ${sets.join(', ')} WHERE client_id=?`).bind(...vals).run();
  // A Table ID was just set for the first time — clear any cached column-name resolution from a
  // stale/empty lookup so the next billing event re-resolves against the real table.
  if(body.nocodb_customers_table_id) _saasColumnNameCache.delete(String(body.nocodb_customers_table_id).trim());
  return json({ok:true});
}

// ── Accounts — the client's own NocoDB customers table, read/written directly (no D1 shadow copy).
// GET returns every row's full original columns plus the saas_* computed fields, with name/email/
// phone additionally surfaced under generic keys (alias-resolved) so the UI doesn't need to know
// the client's actual column names to render a card. PATCH only ever writes saas_*-prefixed fields
// — the column-ownership safety rule applies here exactly as it does to the billing webhook path.
async function handleSaasCustomersList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const tableId=await saasResolveCustomersTable(env, clientId);
  if(!tableId) return json({list:[], nocodb_not_configured:true});
  await ensureSaasCustomerFields(env, tableId);
  const rows=await saasFetchAllCustomers(env, tableId);
  const list=rows.map(row=>({
    ...row,
    Id:row.Id,
    _name:saasGetCustomerField(row, SAAS_CUSTOMER_FIELD_ALIASES.name)||`Customer #${row.Id}`,
    _email:saasGetCustomerField(row, SAAS_CUSTOMER_FIELD_ALIASES.email)||'',
    _phone:saasGetCustomerField(row, SAAS_CUSTOMER_FIELD_ALIASES.phone)||'',
  }));
  return json({list, table_id:tableId});
}
async function handleSaasCustomerUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const tableId=await saasResolveCustomersTable(env, clientId);
  if(!tableId) return json({error:'No NocoDB customers table configured'}, 400);
  await ensureSaasCustomerFields(env, tableId);
  const fields={};
  for(const f of SAAS_CUSTOMER_COMPUTED_FIELDS){
    const key=f.replace(/^saas_/,'');
    if(body[key]!==undefined) fields[f]=body[key]===null?'':String(body[key]).slice(0,500);
  }
  if(!Object.keys(fields).length) return json({ok:true});
  await saasWriteCustomerFields(env, tableId, body.id, fields);
  return json({ok:true});
}

// ── Unmatched billing events — a webhook charge that couldn't be matched to a row in the client's
// NocoDB customers table by email/phone. Never blind-written into that live table on a guess;
// surfaced here so a human can link it to the right account by hand.
async function handleSaasUnmatchedEventsList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {results}=await env.DB.prepare(`SELECT * FROM saas_unmatched_billing_events WHERE client_id=? AND resolved_at IS NULL ORDER BY occurred_at DESC LIMIT 200`).bind(Number(payload.cid)).all();
  return json({list:(results||[]).map(r=>({...r, Id:r.id}))});
}
async function handleSaasUnmatchedEventResolve(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const body=await request.json().catch(()=>({}));
  if(!body.id || !body.nocodb_customer_id) return json({error:'id and nocodb_customer_id required'}, 400);
  const evt=await env.DB.prepare(`SELECT * FROM saas_unmatched_billing_events WHERE id=? AND client_id=?`).bind(Number(body.id), clientId).first();
  if(!evt) return json({error:'Not found'}, 404);
  const tableId=await saasResolveCustomersTable(env, clientId);
  if(!tableId) return json({error:'No NocoDB customers table configured'}, 400);
  const custRow=await saasFetchCustomerById(env, tableId, body.nocodb_customer_id);
  if(!custRow) return json({error:'That NocoDB customer id was not found in the configured table'}, 404);
  const now=new Date().toISOString();
  // Replay the same effect saasApplyBillingEvent would have had, now that we know the account.
  if(evt.action==='payment_succeeded'){
    await env.DB.prepare(`INSERT INTO saas_collections (client_id, nocodb_customer_id, amount, currency, source, occurred_at, created_at) VALUES (?,?,?,?,?,?,?)`)
      .bind(clientId, String(body.nocodb_customer_id), evt.amount||0, evt.currency||'USD', 'webhook_reconciled', evt.occurred_at, now).run();
  }
  await ensureSaasCustomerFields(env, tableId);
  if(evt.action==='subscription_cancelled'){
    await saasWriteCustomerFields(env, tableId, body.nocodb_customer_id, {saas_lifecycle_stage:'churned'});
  }else if(evt.action==='subscription_active' || evt.action==='payment_succeeded'){
    await saasWriteCustomerFields(env, tableId, body.nocodb_customer_id, {
      saas_lifecycle_stage: custRow.saas_lifecycle_stage==='churned'||!custRow.saas_lifecycle_stage?'active':custRow.saas_lifecycle_stage,
      saas_plan_name: evt.plan_name||custRow.saas_plan_name||'',
    });
  }
  await env.DB.prepare(`UPDATE saas_unmatched_billing_events SET resolved_at=?, resolved_nocodb_customer_id=? WHERE id=?`).bind(now, String(body.nocodb_customer_id), evt.id).run();
  return json({ok:true});
}

// ── Reports — GET /saas/reports, dashboard.html's new "📈 SaaS" Reports sub-tab. Recomputed from
// each client's NocoDB customer rows' saas_* fields + saas_collections, instead of fp_customers.
async function handleSaasReports(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const tableId=await saasResolveCustomersTable(env, clientId);
  if(!tableId){
    return json({months:[], mrr:0, active_accounts:0, logo_churn_rate:0, health_distribution:{healthy:0,neutral:0,at_risk:0}, at_risk_accounts:[], renewal_pipeline:[], activation_funnel:[], expansion_candidates:[], nocodb_not_configured:true});
  }
  const months=6;
  const since=new Date(); since.setMonth(since.getMonth()-(months-1)); since.setDate(1);

  const {results:collections}=await env.DB.prepare(`SELECT occurred_at, amount, currency FROM saas_collections WHERE client_id=? AND occurred_at>=?`).bind(clientId, since.toISOString()).all();
  const byMonth={};
  (collections||[]).forEach(c=>{ const m=c.occurred_at.slice(0,7); if(!byMonth[m]) byMonth[m]={key:m, revenue:0}; byMonth[m].revenue+=Number(c.amount)||0; });

  const allCust=await saasFetchAllCustomers(env, tableId);
  const active=allCust.filter(c=>c.saas_lifecycle_stage!=='churned');
  const churned=allCust.filter(c=>c.saas_lifecycle_stage==='churned');
  const mrr=active.reduce((s,c)=>s+(Number(c.saas_monthly_value)||0),0);
  const logoChurnRate=allCust.length?Math.round((churned.length/allCust.length)*1000)/10:0;

  const custName=c=>saasGetCustomerField(c, SAAS_CUSTOMER_FIELD_ALIASES.name)||`Customer #${c.Id}`;
  const healthDistribution={healthy:0, neutral:0, at_risk:0};
  active.forEach(c=>{ const s=c.saas_health_score!=null?Number(c.saas_health_score):null; if(s==null||Number.isNaN(s)) return; if(s>=70) healthDistribution.healthy++; else if(s>=40) healthDistribution.neutral++; else healthDistribution.at_risk++; });
  const atRisk=active.filter(c=>c.saas_health_score!=null && Number(c.saas_health_score)<40).sort((a,b)=>Number(a.saas_health_score)-Number(b.saas_health_score)).slice(0,10).map(c=>({name:custName(c), health_score:Number(c.saas_health_score), mrr:Number(c.saas_monthly_value)||0}));

  const todayStr=new Date().toISOString().slice(0,10);
  const renewalPipeline=active.filter(c=>c.saas_renewal_date).map(c=>({name:custName(c), renewal_date:c.saas_renewal_date, days_out:Math.round((new Date(c.saas_renewal_date)-new Date(todayStr))/86400000)}))
    .filter(c=>c.days_out>=0 && c.days_out<=90).sort((a,b)=>a.days_out-b.days_out);

  const {results:milestoneDefs}=await env.DB.prepare(`SELECT milestone_key, label FROM saas_activation_milestones WHERE client_id=?`).bind(clientId).all();
  const activationFunnel=[];
  for(const m of (milestoneDefs||[])){
    const {results} =await env.DB.prepare(`SELECT COUNT(*) n FROM saas_account_milestones WHERE client_id=? AND milestone_key=? AND completed_at IS NOT NULL`).bind(clientId, m.milestone_key).all();
    activationFunnel.push({milestone:m.label, completed:results?.[0]?.n||0});
  }

  const expansionCandidates=active.filter(c=>c.saas_seat_count!=null && Number(c.saas_seat_count)>0).map(c=>({name:custName(c), seat_count:Number(c.saas_seat_count)})).slice(0,10);

  return json({
    months:Object.values(byMonth).sort((a,b)=>a.key.localeCompare(b.key)),
    mrr:Math.round(mrr*100)/100, active_accounts:active.length, logo_churn_rate:logoChurnRate,
    health_distribution:healthDistribution, at_risk_accounts:atRisk,
    renewal_pipeline:renewalPipeline, activation_funnel:activationFunnel, expansion_candidates:expansionCandidates,
  });
}

// ── Hospitality module (frontend/dashboard.html "🏨 Hospitality" nav tab — houseboats/hotels/
// tourism stays) — fully D1 (migrations/0009_hospitality.sql), unlike the Agency/Recruit/
// Appointments modules' per-client dynamic NocoDB tables: a date-range + occupancy-pricing data
// shape nothing else in the app reads, so there's no reason to pay NocoDB's per-client
// table-creation overhead for it. Every route below derives client_id from the session and checks
// row ownership the same way the Accounting module's routes do. ──
const HOSPITALITY_BOOKING_STATUSES=new Set(['inquiry','confirmed','checked_in','checked_out','cancelled']);
// A unit is considered "occupied" for overlap/availability purposes only once a booking is past
// the inquiry stage — an unconfirmed inquiry shouldn't block someone else from booking the same
// dates.
const HOSPITALITY_OCCUPYING_STATUSES=new Set(['confirmed','checked_in','checked_out']);

async function handleHospitalityUnitsList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {results}=await env.DB.prepare(`SELECT * FROM hospitality_units WHERE client_id=? ORDER BY name ASC`).bind(Number(payload.cid)).all();
  return json({list:(results||[]).map(r=>({...r, Id:r.id}))});
}

async function handleHospitalityUnitCreate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.name) return json({error:'name required'}, 400);
  const fields={
    client_id:Number(payload.cid), name:String(body.name).trim().slice(0,140),
    unit_type:String(body.unit_type||'').trim().slice(0,80),
    capacity_adults:Number(body.capacity_adults)||2, capacity_children:Number(body.capacity_children)||0,
    amenities:String(body.amenities||'').trim().slice(0,500),
    base_rate:Number(body.base_rate)||0, weekend_rate:body.weekend_rate?Number(body.weekend_rate):null,
    currency:String(body.currency||'INR').trim().slice(0,10).toUpperCase(),
    description:String(body.description||'').trim().slice(0,1000),
    active:body.active===false?0:1, created_at:new Date().toISOString(),
  };
  const r=await env.DB.prepare(`INSERT INTO hospitality_units
    (client_id, name, unit_type, capacity_adults, capacity_children, amenities, base_rate, weekend_rate, currency, description, active, created_at)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`)
    .bind(fields.client_id, fields.name, fields.unit_type, fields.capacity_adults, fields.capacity_children, fields.amenities, fields.base_rate, fields.weekend_rate, fields.currency, fields.description, fields.active, fields.created_at)
    .run();
  return json({...fields, Id:r.meta.last_row_id});
}

async function findHospitalityUnit(env, id){
  return await env.DB.prepare(`SELECT * FROM hospitality_units WHERE id=?`).bind(Number(id)).first();
}

async function handleHospitalityUnitUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const existing=await findHospitalityUnit(env, body.id);
  if(!existing || String(existing.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  const sets=[], vals=[];
  if(body.name!==undefined){ sets.push('name=?'); vals.push(String(body.name).trim().slice(0,140)); }
  if(body.unit_type!==undefined){ sets.push('unit_type=?'); vals.push(String(body.unit_type).trim().slice(0,80)); }
  if(body.capacity_adults!==undefined){ sets.push('capacity_adults=?'); vals.push(Number(body.capacity_adults)||2); }
  if(body.capacity_children!==undefined){ sets.push('capacity_children=?'); vals.push(Number(body.capacity_children)||0); }
  if(body.amenities!==undefined){ sets.push('amenities=?'); vals.push(String(body.amenities).trim().slice(0,500)); }
  if(body.base_rate!==undefined){ sets.push('base_rate=?'); vals.push(Number(body.base_rate)||0); }
  if(body.weekend_rate!==undefined){ sets.push('weekend_rate=?'); vals.push(body.weekend_rate?Number(body.weekend_rate):null); }
  if(body.currency!==undefined){ sets.push('currency=?'); vals.push(String(body.currency).trim().slice(0,10).toUpperCase()); }
  if(body.description!==undefined){ sets.push('description=?'); vals.push(String(body.description).trim().slice(0,1000)); }
  if(body.active!==undefined){ sets.push('active=?'); vals.push(body.active?1:0); }
  // Photos/video (SETUP.md "Hospitality module — unit photos/video") — a plain URL string, same
  // autosave-on-blur PATCH every other unit field already uses, now that they're a pasted Google
  // Drive link instead of an uploaded file. Deliberately not domain-restricted here (the frontend
  // labels the field as a Drive link and nudges for one, but any public URL still works — the
  // send-time fetch in hospitalitySendUnitMedia() only *specially handles* Drive's own link shapes
  // for reliable byte-fetching; a non-Drive URL just won't attach automatically in chat).
  if(body.image_url_1!==undefined){ sets.push('image_url_1=?'); vals.push(body.image_url_1?String(body.image_url_1).trim().slice(0,500):null); }
  if(body.image_url_2!==undefined){ sets.push('image_url_2=?'); vals.push(body.image_url_2?String(body.image_url_2).trim().slice(0,500):null); }
  if(body.image_url_3!==undefined){ sets.push('image_url_3=?'); vals.push(body.image_url_3?String(body.image_url_3).trim().slice(0,500):null); }
  if(body.video_url!==undefined){ sets.push('video_url=?'); vals.push(body.video_url?String(body.video_url).trim().slice(0,500):null); }
  if(!sets.length) return json({ok:true});
  vals.push(Number(body.id));
  await env.DB.prepare(`UPDATE hospitality_units SET ${sets.join(', ')} WHERE id=?`).bind(...vals).run();
  return json({ok:true});
}

async function handleHospitalityUnitDelete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const existing=await findHospitalityUnit(env, body.id);
  if(!existing || String(existing.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  await env.DB.prepare(`DELETE FROM hospitality_units WHERE id=?`).bind(Number(body.id)).run();
  await env.DB.prepare(`DELETE FROM hospitality_blocked_dates WHERE unit_id=?`).bind(Number(body.id)).run();
  await env.DB.prepare(`DELETE FROM hospitality_rate_overrides WHERE unit_id=?`).bind(Number(body.id)).run();
  await env.DB.prepare(`DELETE FROM hospitality_media_sent WHERE unit_id=?`).bind(Number(body.id)).run();
  await hospitalityDeleteAllUnitMedia(env, payload.cid, body.id);
  return json({ok:true});
}

// ── Unit media (2-3 photos + 1 video, SETUP.md "Hospitality module") — image_url_*/video_url
// columns hold a pasted Google Drive share link (the current, "paste a link" flow — see
// hospitalitySendUnitMedia() below for how those get fetched/attached at send time). The upload
// endpoints below (R2-backed, HOSPITALITY_MEDIA binding) are kept only for backward compatibility
// with units that already had a file uploaded before this switch — nothing in the current frontend
// calls handleHospitalityUnitMediaUpload anymore, but hospitalitySendUnitMedia still knows how to
// serve an already-stored R2 URL, and handleHospitalityUnitMediaDelete still lets a rep clear an old
// one via the same remove button. R2 key extension isn't tracked separately in D1, so delete/replace
// try every extension that upload validation could ever have accepted — an R2 delete on a
// nonexistent key is a harmless no-op.
const HOSPITALITY_MEDIA_SLOTS={image1:'image_url_1', image2:'image_url_2', image3:'image_url_3', video:'video_url'};
const HOSPITALITY_MEDIA_MAX_BYTES=9*1024*1024;
const HOSPITALITY_IMAGE_EXTS=['jpg','jpeg','png','webp','gif'];
const HOSPITALITY_VIDEO_EXTS=['mp4','mov','webm','mkv','avi'];
function hospitalityMediaKey(clientId, unitId, slot, ext){ return `hosp/${clientId}/${unitId}/${slot}.${ext}`; }
async function hospitalityDeleteAllUnitMedia(env, clientId, unitId){
  for(const slot of Object.keys(HOSPITALITY_MEDIA_SLOTS)){
    const exts=slot==='video'?HOSPITALITY_VIDEO_EXTS:HOSPITALITY_IMAGE_EXTS;
    for(const ext of exts){ try{ await env.HOSPITALITY_MEDIA.delete(hospitalityMediaKey(clientId, unitId, slot, ext)); }catch(e){} }
  }
}

async function handleHospitalityUnitMediaUpload(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const form=await request.formData().catch(()=>null);
  if(!form) return json({error:'multipart form data required'}, 400);
  const unitId=form.get('unit_id'), slot=form.get('slot'), file=form.get('file');
  if(!unitId||!slot||!file) return json({error:'unit_id, slot and file required'}, 400);
  const column=HOSPITALITY_MEDIA_SLOTS[slot];
  if(!column) return json({error:'Invalid slot'}, 400);
  const unit=await findHospitalityUnit(env, unitId);
  if(!unit || String(unit.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  if(file.size>HOSPITALITY_MEDIA_MAX_BYTES) return json({error:'File is too large — max 9 MB.'}, 400);
  const isVideoSlot=slot==='video';
  const mime=(file.type||'').split(';')[0];
  if(isVideoSlot && !mime.startsWith('video/')) return json({error:'The video slot needs a video file.'}, 400);
  if(!isVideoSlot && !mime.startsWith('image/')) return json({error:'Photo slots need an image file.'}, 400);
  const ext=(mime.split('/')[1]||'').replace(/[^a-z0-9]/gi,'').toLowerCase()||(isVideoSlot?'mp4':'jpg');
  const key=hospitalityMediaKey(payload.cid, unitId, slot, ext);
  await env.HOSPITALITY_MEDIA.put(key, await file.arrayBuffer(), {httpMetadata:{contentType:mime||'application/octet-stream'}});
  const url=`${env.WORKER_BASE_URL}/hospitality/media/${key}`;
  await env.DB.prepare(`UPDATE hospitality_units SET ${column}=? WHERE id=?`).bind(url, Number(unitId)).run();
  return json({ok:true, url, slot});
}

async function handleHospitalityUnitMediaDelete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const {unit_id, slot}=body;
  if(!unit_id||!slot) return json({error:'unit_id and slot required'}, 400);
  const column=HOSPITALITY_MEDIA_SLOTS[slot];
  if(!column) return json({error:'Invalid slot'}, 400);
  const unit=await findHospitalityUnit(env, unit_id);
  if(!unit || String(unit.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  const exts=slot==='video'?HOSPITALITY_VIDEO_EXTS:HOSPITALITY_IMAGE_EXTS;
  for(const ext of exts){ try{ await env.HOSPITALITY_MEDIA.delete(hospitalityMediaKey(payload.cid, unit_id, slot, ext)); }catch(e){} }
  await env.DB.prepare(`UPDATE hospitality_units SET ${column}=NULL WHERE id=?`).bind(Number(unit_id)).run();
  return json({ok:true});
}

// Public, no session — Chatwoot/WhatsApp's own media fetch and a plain <img>/<video> tag in the
// browser both need to load this with no Authorization header. The key (client/unit/slot, no
// guessable sequence) isn't obscured further than that — same trust model as the ecommerce
// product image URLs this Worker already forwards from Shopify's own public CDN, and this is
// lower-sensitivity content (marketing photos of a room/houseboat) to begin with.
async function handleHospitalityMediaServe(env, key){
  if(!key) return json({error:'Not found'}, 404);
  const obj=await env.HOSPITALITY_MEDIA.get(key);
  if(!obj) return json({error:'Not found'}, 404);
  const headers=new Headers();
  obj.writeHttpMetadata(headers);
  headers.set('etag', obj.httpEtag);
  headers.set('Cache-Control','public, max-age=86400');
  return new Response(obj.body, {headers});
}

// A general-enquiry heuristic for engineMaybeSendHospitalityMedia's fallback path below — not an
// LLM call (same "cheap and predictable, can over/under-match" tradeoff as the unit-name
// substring match), just a keyword list for "asking what's available at all" phrasing.
const HOSPITALITY_GENERAL_ENQUIRY_RE=/\b(rooms?|units?|houseboats?|stays?|accommodations?|available|availability|options?|packages?|tariffs?|rates?|prices?|pricing|bookings?|vacanc(?:y|ies))\b/i;

// Extracts a Google Drive file id from whichever share-link shape a rep pasted — the normal
// "share" link (drive.google.com/file/d/<id>/view?usp=sharing) or an "open"/"uc" link
// (?id=<id>) — so the rest of this file can build its own direct-content URL regardless of which
// one was pasted. Returns null for anything that doesn't look like a Drive link at all (a legacy
// R2-hosted URL, or some other public URL a rep pasted instead — see hospitalitySendUnitMedia()).
function driveFileId(url){
  if(!url) return null;
  let m=String(url).match(/\/file\/d\/([a-zA-Z0-9_-]+)/); if(m) return m[1];
  m=String(url).match(/[?&]id=([a-zA-Z0-9_-]+)/); if(m) return m[1];
  return null;
}
// Google Drive serves an HTML "Google Drive can't scan this file for viruses" interstitial
// instead of the raw bytes for some files (mostly larger ones) unless a `confirm=` token is also
// present. Appending `confirm=t` upfront skips that for most files without needing to scrape a
// token first; driveFetchFile below falls back to extracting and replaying the real token from
// the interstitial's own HTML if the file still needs it.
function driveDirectUrl(fileId, confirmToken){
  return `https://drive.google.com/uc?export=download&id=${fileId}&confirm=${confirmToken||'t'}`;
}
// Fetches a Google Drive file's actual bytes for forwarding as a WhatsApp/Chatwoot attachment —
// the file must be shared "Anyone with the link" for this Worker (an anonymous fetch, no Drive
// account behind it) to read it at all. Returns null (never throws) on anything that didn't work
// out — an unshared/deleted file, or a file too large for the confirm=t bypass above to satisfy —
// so callers can just skip that one item rather than attaching garbage/an HTML page as "the photo".
async function driveFetchFile(fileId){
  try{
    let r=await fetch(driveDirectUrl(fileId));
    let ct=(r.headers.get('content-type')||'');
    if(ct.includes('text/html')){
      const html=await r.text();
      const m=html.match(/confirm=([0-9A-Za-z_-]+)/);
      if(!m) return null;
      r=await fetch(driveDirectUrl(fileId, m[1]));
      ct=(r.headers.get('content-type')||'');
      if(ct.includes('text/html')) return null; // still the interstitial — give up rather than send it as-is
    }
    if(!r.ok) return null;
    return {blob:await r.blob(), contentType:ct};
  }catch(e){ return null; }
}

// Guesses a sensible attachment filename from the fetched content-type — WhatsApp/Chatwoot render
// an attachment differently (inline video player, image preview, audio player, document icon)
// based on its extension, not just the MIME type header, so a bare extension-less blob would often
// show up as a generic "document" regardless of what it actually is.
function driveGuessFilename(contentType){
  const map={'video/mp4':'video.mp4','video/quicktime':'video.mov','video/webm':'video.webm',
    'image/jpeg':'image.jpg','image/png':'image.png','image/webp':'image.webp','image/gif':'image.gif',
    'audio/mpeg':'audio.mp3','audio/ogg':'audio.ogg','audio/wav':'audio.wav','audio/mp4':'audio.m4a',
    'application/pdf':'document.pdf'};
  return map[(contentType||'').split(';')[0].trim()]||'file';
}
// Fetches one Google Drive file (video/image/audio/PDF) and forwards it into a Chatwoot
// conversation as a real attachment — the general-purpose version of hospitalitySendUnitMedia's
// per-item send, shared by the Automations & Flow module's send_whatsapp_media step and the
// classic follow-up sequence's per-variant media attachment (see pickFollowupVariant/
// handleBroadcastFollowupSend below). Returns false (never throws) on anything that didn't work —
// an unshared file, a bad link, or a Chatwoot send failure — so callers can treat it as best-effort
// exactly like every other WhatsApp send in this file.
async function sendDriveMediaToChatwoot(c, convId, driveUrl, caption){
  const fileId=driveFileId(driveUrl);
  if(!fileId) return false;
  const fetched=await driveFetchFile(fileId);
  if(!fetched) return false;
  const fd=new FormData();
  fd.append('content', caption||'');
  fd.append('message_type','outgoing'); fd.append('private','false');
  fd.append('attachments[]', fetched.blob, driveGuessFilename(fetched.contentType));
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {method:'POST', headers:{api_access_token:c.chatwoot_token}, body:fd});
  return r.ok;
}

// Sends one unit's photos/video into the chat as real attachments and marks it sent so it's never
// repeated for this lead. Each item's stored URL is either a legacy R2-hosted one from before the
// Google Drive switch (fetched straight from the R2 binding, same as before) or a Google Drive
// share link (fetched via driveFetchFile above) — whichever it is, every non-empty slot on the
// unit gets sent, not just the first one that resolves. Shared by both
// engineMaybeSendHospitalityMedia branches below (a specific unit named, or the whole active
// catalog on a general enquiry).
async function hospitalitySendUnitMedia(env, c, clientId, convId, leadId, unit){
  const items=[
    {url:unit.image_url_1, name:'photo1.jpg'},
    {url:unit.image_url_2, name:'photo2.jpg'},
    {url:unit.image_url_3, name:'photo3.jpg'},
    {url:unit.video_url, name:'video.mp4'},
  ].filter(m=>m.url);
  if(!items.length) return false;
  let sentAny=false;
  for(let i=0;i<items.length;i++){
    let blob=null;
    const marker='/hospitality/media/';
    const idx=items[i].url.indexOf(marker);
    if(idx!==-1){
      const key=items[i].url.slice(idx+marker.length);
      const obj=await env.HOSPITALITY_MEDIA.get(key);
      if(obj) blob=await obj.blob();
    }else{
      const fileId=driveFileId(items[i].url);
      if(fileId){
        const fetched=await driveFetchFile(fileId);
        if(fetched) blob=fetched.blob;
      }
    }
    if(!blob) continue;
    const fd=new FormData();
    fd.append('content', i===0?`Here's a look at ${unit.name} 📸`:'');
    fd.append('message_type','outgoing'); fd.append('private','false');
    fd.append('attachments[]', blob, items[i].name);
    const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {method:'POST', headers:{api_access_token:c.chatwoot_token}, body:fd});
    if(r.ok) sentAny=true;
  }
  if(sentAny){
    await env.DB.prepare(`INSERT OR IGNORE INTO hospitality_media_sent (client_id, lead_id, unit_id, sent_at) VALUES (?,?,?,?)`)
      .bind(Number(clientId), leadId, unit.id, new Date().toISOString()).run();
  }
  return sentAny;
}

// Auto-sends unit photos/video into the chat, in two modes:
//  - Specific enquiry: a lead's message names one active unit — send only that unit's media,
//    simple case-insensitive substring match on the unit's name (see SETUP.md for why this isn't
//    an LLM call and its known over/under-match tradeoff).
//  - General enquiry: no specific unit named, but the message reads like someone asking what's
//    available at all (HOSPITALITY_GENERAL_ENQUIRY_RE) — send every active unit's photos once,
//    so a first-time enquirer sees the whole catalog instead of getting nothing until they happen
//    to name a unit. Gated on this lead never having received ANY hospitality media before
//    (hospitality_media_sent), so it only ever fires once per lead, not on every message that
//    happens to contain a word like "available".
// "Once per session" in both modes means once per (lead, unit) ever, not re-sent on every later
// message that happens to mention the same unit (or ask about availability) again.
async function engineMaybeSendHospitalityMedia(env, c, clientId, convId, resolvedLeadId, userText){
  if(c.hospitality_enabled!=='Yes' || !userText || !resolvedLeadId || !convId) return;
  if(!c.chatwoot_base||!c.chatwoot_account_id||!c.chatwoot_token) return;
  try{
    const {results:units}=await env.DB.prepare(`SELECT * FROM hospitality_units WHERE client_id=? AND active=1`).bind(Number(clientId)).all();
    if(!units || !units.length) return;
    const lower=userText.toLowerCase();
    const specificUnit=units.find(u=>u.name && u.name.trim().length>=4 && lower.includes(u.name.trim().toLowerCase()));
    if(specificUnit){
      const already=await env.DB.prepare(`SELECT id FROM hospitality_media_sent WHERE lead_id=? AND unit_id=?`).bind(resolvedLeadId, specificUnit.id).first();
      if(already) return;
      await hospitalitySendUnitMedia(env, c, clientId, convId, resolvedLeadId, specificUnit);
      return;
    }
    if(!HOSPITALITY_GENERAL_ENQUIRY_RE.test(lower)) return;
    const alreadyAny=await env.DB.prepare(`SELECT id FROM hospitality_media_sent WHERE lead_id=? LIMIT 1`).bind(resolvedLeadId).first();
    if(alreadyAny) return;
    for(const unit of units) await hospitalitySendUnitMedia(env, c, clientId, convId, resolvedLeadId, unit);
  }catch(e){ await reportOpsError(env, 'engineMaybeSendHospitalityMedia', e, {clientId, convId}); }
}

async function handleHospitalityBlockedDateCreate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.unit_id||!body.date) return json({error:'unit_id and date required'}, 400);
  const unit=await findHospitalityUnit(env, body.unit_id);
  if(!unit || String(unit.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  await env.DB.prepare(`INSERT OR REPLACE INTO hospitality_blocked_dates (client_id, unit_id, date, reason, created_at) VALUES (?,?,?,?,?)`)
    .bind(Number(payload.cid), Number(body.unit_id), String(body.date), String(body.reason||'').trim().slice(0,200), new Date().toISOString()).run();
  return json({ok:true});
}

async function handleHospitalityBlockedDateDelete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.unit_id||!body.date) return json({error:'unit_id and date required'}, 400);
  const unit=await findHospitalityUnit(env, body.unit_id);
  if(!unit || String(unit.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  await env.DB.prepare(`DELETE FROM hospitality_blocked_dates WHERE unit_id=? AND date=?`).bind(Number(body.unit_id), String(body.date)).run();
  return json({ok:true});
}

async function handleHospitalityRateOverrideSave(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.unit_id||!body.date) return json({error:'unit_id and date required'}, 400);
  const unit=await findHospitalityUnit(env, body.unit_id);
  if(!unit || String(unit.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  if(body.rate===null || body.rate===''){
    await env.DB.prepare(`DELETE FROM hospitality_rate_overrides WHERE unit_id=? AND date=?`).bind(Number(body.unit_id), String(body.date)).run();
    return json({ok:true, cleared:true});
  }
  await env.DB.prepare(`INSERT OR REPLACE INTO hospitality_rate_overrides (client_id, unit_id, date, rate, created_at) VALUES (?,?,?,?,?)`)
    .bind(Number(payload.cid), Number(body.unit_id), String(body.date), Number(body.rate), new Date().toISOString()).run();
  return json({ok:true});
}

// Calendar view for one unit over a date range — blocked dates, rate overrides, and booked ranges
// (from hospitality_bookings, occupying statuses only) merged into one per-date status list, so
// the frontend can render a month grid without stitching three separate fetches together itself.
async function handleHospitalityAvailability(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const url=new URL(request.url);
  const unitId=url.searchParams.get('unit_id');
  const start=url.searchParams.get('start');
  const end=url.searchParams.get('end');
  if(!unitId||!start||!end) return json({error:'unit_id, start and end required'}, 400);
  const unit=await findHospitalityUnit(env, unitId);
  if(!unit || String(unit.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);

  const {results:blocked}=await env.DB.prepare(`SELECT date, reason FROM hospitality_blocked_dates WHERE unit_id=? AND date>=? AND date<?`)
    .bind(Number(unitId), start, end).all();
  const {results:rates}=await env.DB.prepare(`SELECT date, rate FROM hospitality_rate_overrides WHERE unit_id=? AND date>=? AND date<?`)
    .bind(Number(unitId), start, end).all();
  const {results:bookings}=await env.DB.prepare(`SELECT id, check_in, check_out, guest_name, status FROM hospitality_bookings WHERE unit_id=? AND status IN ('confirmed','checked_in','checked_out') AND check_in<? AND check_out>?`)
    .bind(Number(unitId), end, start).all();

  const blockedMap={}; (blocked||[]).forEach(r=>{ blockedMap[r.date]=r.reason||''; });
  const rateMap={}; (rates||[]).forEach(r=>{ rateMap[r.date]=r.rate; });
  // Expand each booking's [check_in, check_out) range into individual occupied dates — a stay's
  // check-out date itself is not occupied (that's the turnover day a new guest can check in).
  const bookedMap={};
  (bookings||[]).forEach(b=>{
    let d=new Date(b.check_in+'T00:00:00Z');
    const outD=new Date(b.check_out+'T00:00:00Z');
    while(d<outD){
      const iso=d.toISOString().slice(0,10);
      if(iso>=start && iso<end) bookedMap[iso]={booking_id:b.id, guest_name:b.guest_name, status:b.status};
      d.setUTCDate(d.getUTCDate()+1);
    }
  });

  const days=[];
  let cur=new Date(start+'T00:00:00Z');
  const endD=new Date(end+'T00:00:00Z');
  while(cur<endD){
    const iso=cur.toISOString().slice(0,10);
    const dow=cur.getUTCDay();
    const isWeekend=dow===0||dow===6;
    const rate=rateMap[iso]!==undefined?rateMap[iso]:(isWeekend&&unit.weekend_rate?unit.weekend_rate:unit.base_rate);
    let status='available';
    if(bookedMap[iso]) status='booked'; else if(blockedMap[iso]!==undefined) status='blocked';
    days.push({date:iso, status, rate, reason:blockedMap[iso]||null, booking:bookedMap[iso]||null});
    cur.setUTCDate(cur.getUTCDate()+1);
  }
  return json({unit:{...unit, Id:unit.id}, days});
}

async function findHospitalityBooking(env, id){
  return await env.DB.prepare(`SELECT * FROM hospitality_bookings WHERE id=?`).bind(Number(id)).first();
}

// Overlap check shared by create/update — an occupying-status booking on the same unit whose
// [check_in, check_out) range intersects the requested range blocks it. excludeId lets an update
// check against every OTHER booking without tripping over itself.
async function hospitalityHasOverlap(env, clientId, unitId, checkIn, checkOut, excludeId){
  let sql=`SELECT id FROM hospitality_bookings WHERE client_id=? AND unit_id=? AND status IN ('confirmed','checked_in','checked_out') AND check_in<? AND check_out>?`;
  const binds=[Number(clientId), Number(unitId), checkOut, checkIn];
  if(excludeId){ sql+=` AND id!=?`; binds.push(Number(excludeId)); }
  const {results}=await env.DB.prepare(sql).bind(...binds).all();
  return (results||[]).length>0;
}

async function handleHospitalityBookingsList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const url=new URL(request.url);
  const unitId=url.searchParams.get('unit_id');
  let sql=`SELECT * FROM hospitality_bookings WHERE client_id=?`;
  const binds=[Number(payload.cid)];
  if(unitId){ sql+=` AND unit_id=?`; binds.push(Number(unitId)); }
  sql+=` ORDER BY check_in DESC LIMIT 1000`;
  const {results}=await env.DB.prepare(sql).bind(...binds).all();
  return json({list:(results||[]).map(r=>({...r, Id:r.id}))});
}

function hospitalityNights(checkIn, checkOut){
  const ms=new Date(checkOut+'T00:00:00Z').getTime()-new Date(checkIn+'T00:00:00Z').getTime();
  return Math.max(1, Math.round(ms/86400000));
}

async function handleHospitalityBookingCreate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.unit_id||!body.check_in||!body.check_out) return json({error:'unit_id, check_in and check_out required'}, 400);
  if(!(body.check_out>body.check_in)) return json({error:'check_out must be after check_in'}, 400);
  const unit=await findHospitalityUnit(env, body.unit_id);
  if(!unit || String(unit.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  const status=HOSPITALITY_BOOKING_STATUSES.has(body.status)?body.status:'inquiry';
  if(HOSPITALITY_OCCUPYING_STATUSES.has(status) && await hospitalityHasOverlap(env, payload.cid, body.unit_id, body.check_in, body.check_out, null)){
    return json({error:'This unit is already booked for part of that date range.'}, 409);
  }
  const nights=hospitalityNights(body.check_in, body.check_out);
  const rate=Number(body.rate_per_night)||unit.base_rate||0;
  const fields={
    client_id:Number(payload.cid), unit_id:Number(body.unit_id), lead_id:body.lead_id?Number(body.lead_id):null,
    guest_name:String(body.guest_name||'').trim().slice(0,140), guest_phone:String(body.guest_phone||'').trim().slice(0,40),
    check_in:String(body.check_in), check_out:String(body.check_out), nights,
    adults:Number(body.adults)||1, children:Number(body.children)||0,
    rate_per_night:rate, total_amount:body.total_amount!==undefined?Number(body.total_amount):rate*nights,
    deposit_amount:Number(body.deposit_amount)||0, currency:String(body.currency||unit.currency||'INR').trim().slice(0,10).toUpperCase(),
    status, notes:String(body.notes||'').trim().slice(0,1000), created_at:new Date().toISOString(),
  };
  const r=await env.DB.prepare(`INSERT INTO hospitality_bookings
    (client_id, unit_id, lead_id, guest_name, guest_phone, check_in, check_out, nights, adults, children, rate_per_night, total_amount, deposit_amount, currency, status, notes, created_at)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
    .bind(fields.client_id, fields.unit_id, fields.lead_id, fields.guest_name, fields.guest_phone, fields.check_in, fields.check_out, fields.nights, fields.adults, fields.children, fields.rate_per_night, fields.total_amount, fields.deposit_amount, fields.currency, fields.status, fields.notes, fields.created_at)
    .run();
  return json({...fields, Id:r.meta.last_row_id});
}

async function handleHospitalityBookingUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const existing=await findHospitalityBooking(env, body.id);
  if(!existing || String(existing.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  const nextCheckIn=body.check_in!==undefined?String(body.check_in):existing.check_in;
  const nextCheckOut=body.check_out!==undefined?String(body.check_out):existing.check_out;
  const nextUnitId=body.unit_id!==undefined?Number(body.unit_id):existing.unit_id;
  const nextStatus=body.status!==undefined&&HOSPITALITY_BOOKING_STATUSES.has(body.status)?body.status:existing.status;
  if(!(nextCheckOut>nextCheckIn)) return json({error:'check_out must be after check_in'}, 400);
  if(HOSPITALITY_OCCUPYING_STATUSES.has(nextStatus) && await hospitalityHasOverlap(env, payload.cid, nextUnitId, nextCheckIn, nextCheckOut, existing.id)){
    return json({error:'This unit is already booked for part of that date range.'}, 409);
  }
  const sets=['unit_id=?','check_in=?','check_out=?','nights=?','status=?'];
  const vals=[nextUnitId, nextCheckIn, nextCheckOut, hospitalityNights(nextCheckIn, nextCheckOut), nextStatus];
  if(body.guest_name!==undefined){ sets.push('guest_name=?'); vals.push(String(body.guest_name).trim().slice(0,140)); }
  if(body.guest_phone!==undefined){ sets.push('guest_phone=?'); vals.push(String(body.guest_phone).trim().slice(0,40)); }
  if(body.adults!==undefined){ sets.push('adults=?'); vals.push(Number(body.adults)||1); }
  if(body.children!==undefined){ sets.push('children=?'); vals.push(Number(body.children)||0); }
  if(body.rate_per_night!==undefined){ sets.push('rate_per_night=?'); vals.push(Number(body.rate_per_night)||0); }
  if(body.total_amount!==undefined){ sets.push('total_amount=?'); vals.push(Number(body.total_amount)||0); }
  if(body.deposit_amount!==undefined){ sets.push('deposit_amount=?'); vals.push(Number(body.deposit_amount)||0); }
  if(body.currency!==undefined){ sets.push('currency=?'); vals.push(String(body.currency).trim().slice(0,10).toUpperCase()); }
  if(body.notes!==undefined){ sets.push('notes=?'); vals.push(String(body.notes).trim().slice(0,1000)); }
  vals.push(Number(body.id));
  await env.DB.prepare(`UPDATE hospitality_bookings SET ${sets.join(', ')} WHERE id=?`).bind(...vals).run();
  return json({ok:true});
}

async function handleHospitalityBookingDelete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const existing=await findHospitalityBooking(env, body.id);
  if(!existing || String(existing.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  await env.DB.prepare(`DELETE FROM hospitality_bookings WHERE id=?`).bind(Number(body.id)).run();
  return json({ok:true});
}

// Dashboard stats — occupancy rate is booked-nights / (active-units × nights-in-month) for the
// current calendar month; "active units" excludes any unit marked inactive, same as everywhere
// else active/inactive is respected.
async function handleHospitalityStats(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const clientId=Number(payload.cid);
  const now=new Date();
  const monthStart=`${now.getUTCFullYear()}-${String(now.getUTCMonth()+1).padStart(2,'0')}-01`;
  const nextMonth=new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth()+1, 1));
  const monthEnd=nextMonth.toISOString().slice(0,10);
  const daysInMonth=Math.round((nextMonth.getTime()-new Date(monthStart+'T00:00:00Z').getTime())/86400000);

  const {results:units}=await env.DB.prepare(`SELECT id FROM hospitality_units WHERE client_id=? AND active=1`).bind(clientId).all();
  const activeUnitCount=(units||[]).length;

  const {results:monthBookings}=await env.DB.prepare(`SELECT check_in, check_out, total_amount FROM hospitality_bookings WHERE client_id=? AND status IN ('confirmed','checked_in','checked_out') AND check_in<? AND check_out>?`)
    .bind(clientId, monthEnd, monthStart).all();
  let bookedNights=0, revenue=0;
  (monthBookings||[]).forEach(b=>{
    const from=b.check_in>monthStart?b.check_in:monthStart;
    const to=b.check_out<monthEnd?b.check_out:monthEnd;
    const nights=Math.max(0, Math.round((new Date(to+'T00:00:00Z').getTime()-new Date(from+'T00:00:00Z').getTime())/86400000));
    bookedNights+=nights;
    revenue+=Number(b.total_amount)||0;
  });
  const occupancyRate=activeUnitCount>0?Math.round(bookedNights/(activeUnitCount*daysInMonth)*100):0;

  const today=now.toISOString().slice(0,10);
  const in7=new Date(Date.now()+7*86400000).toISOString().slice(0,10);
  const {results:upcomingCheckIns}=await env.DB.prepare(`SELECT id, unit_id, guest_name, check_in, check_out FROM hospitality_bookings WHERE client_id=? AND status IN ('confirmed','checked_in') AND check_in>=? AND check_in<=? ORDER BY check_in ASC LIMIT 20`)
    .bind(clientId, today, in7).all();
  const {results:upcomingCheckOuts}=await env.DB.prepare(`SELECT id, unit_id, guest_name, check_in, check_out FROM hospitality_bookings WHERE client_id=? AND status='checked_in' AND check_out>=? AND check_out<=? ORDER BY check_out ASC LIMIT 20`)
    .bind(clientId, today, in7).all();

  return json({
    total_units:activeUnitCount, occupancy_rate:occupancyRate, revenue_this_month:revenue,
    upcoming_check_ins:upcomingCheckIns||[], upcoming_check_outs:upcomingCheckOuts||[],
  });
}

/* ══════════════════════════════════════════════════════════════════════════════════════════
   MARKETING STUDIO MODULE (SETUP.md "Marketing Studio module") — standalone short-form video
   repurposing tool: upload a long video, auto-transcribe it, edit captions, pick a caption
   style, render a vertical/square/landscape clip, send it out. A genuinely different module from
   the existing WhatsApp/Email "Campaigns" marketing tools (broadcast.html/email-marketing.html)
   — those send messages, this produces video assets — so it gets its own standalone page
   (frontend/marketing-studio.html) and its own D1 tables (migrations/0015_marketing_studio.sql),
   same "new data shape, no existing NocoDB reader" reasoning as ecom_categories/review_config.

   Gating: like the other optional tabs (feat_campaigns_enabled etc., see
   setupFeatureTabToggle in dashboard.html), visibility is controlled by a Clients field —
   `feat_marketing_studio_enabled`. Unlike those, this one defaults OFF (only 'Yes' counts as
   enabled, not "anything other than 'No'") — it's metered (see marketing_minutes_used/limit
   below) and depends on an operator-configured external render pipeline, so it shouldn't
   silently light up for every existing client the moment this ships. As with every feat_*
   flag in this codebase, the gate is frontend-only (the tab/nav button is hidden) — routes below
   don't re-check it, same as /email/*, /accounting/*, etc.

   What actually runs inside this Worker vs. what's delegated out, and why:
   - Upload, project/job bookkeeping, caption editing, style presets, usage metering, and
     WhatsApp delivery are all real, self-contained Worker code (D1 + R2, no external service).
   - Transcription is a single HTTP call to an OpenAI-Whisper-compatible endpoint
     (MARKETING_TRANSCRIBE_API_URL/KEY) — also genuinely runs here, no external orchestration.
   - Rendering (crop to aspect, burn in captions, silence-cut, auto-zoom, background music +
     ducking, watermark) is NOT something a Cloudflare Worker can do — there's no ffmpeg, no GPU,
     and a 9:16 export with caption burn-in is minutes of CPU work, far past what Workers allow
     per request. handleMarketingRenderStart instead posts a full render spec to an
     operator-configured external pipeline (MARKETING_RENDER_WEBHOOK_URL — e.g. a small
     ffmpeg/Remotion service, or Shotstack/Creatomate behind an n8n workflow, same "engine
     outside this repo" shape the WhatsApp bot's n8n engine already uses) and that pipeline calls
     back into POST /marketing/webhook/render-complete when done. Until that env var is set,
     renders fail immediately with a clear error instead of hanging — see SETUP.md for the exact
     request/callback contract an operator needs to implement on the other end. ── */

// Videos upload directly browser -> R2 via a presigned PUT URL (marketingR2PresignPutUrl below),
